def verify_rat_states(connection):
    """
    Verifies if all RATs are in correct ratState via admin api
    Correct states:
                    "NO_CELLS" - RAT not configured on test line
                    "ALL_ENABLED" - all cells from given RAT are enabled
    """
    adm = admin()
    bts_info = adm.get_bts_info(connection=connection)
    present_rats = _get_rats(connection=connection)
    rat_state = bts_info["ratState"]

    for rat in present_rats:
        if rat_state[rat] != 'ALL_ENABLED':
            raise IncorrectRatStateDetected("Detected incorrect ratState: {0} for {1} RAT".format(rat_state[rat], rat))

    log_result("Detected RATs: {} are in "
               "correct ALL_ENABLED state.".format([rat for rat in present_rats]))


def verify_rat_states_for_uncommissioned_bts(connection):
    """
    Verifies if all RATs are in "NO_CELLS" state
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    """
    adm = admin()
    bts_info = adm.get_bts_info(connection=connection)
    rat_state = bts_info["ratState"]
    for rat in ["nr", "lte", "wcdma", "gsm"]:
        if rat_state[rat] != "NO_CELLS":
            raise IncorrectRatStateDetected("Detected incorrect ratState: {0} for {1} RAT".format(rat_state[rat], rat))
    log_result("All detected RATs are in correct state.")


def verify_rat_states_when_cells_are_blocked(connection):
    """
    Verifies if all RATs are in correct ratState via admin api
    Correct states:
                    "NO_CELLS" - RAT not configured on test line
                    "ALL_DISABLED" - all cells from given RAT are blocked
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    """
    adm = admin()
    bts_info = adm.get_bts_info(connection=connection)
    rat_state = bts_info["ratState"]

    for rat, state in rat_state.items():
        if state != 'NO_CELLS' and state != 'ALL_DISABLED':
            raise IncorrectRatStateDetected("Detected incorrect ratState: {0} for {1} RAT".format(state, rat))

    log_result("Detected RATs: {} are in "
               "correct ALL_DISABLED state.".format(sorted([rat for rat, state in rat_state.items()
                                                            if state == 'ALL_DISABLED'])))


def get_rat_statuses(rat, connection):
    """
    Returns statuses from provided RAT: 'operationalState', 'availabilityStatus','proceduralState', 'reasoningStatus'
    and 'workingState'.
    :param rat: RAT name, e.g. "nr", "lte", "wcdma", "gsm"
    :type rat: str
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :return: dictionary with RAT statuses
    """
    infomodel_obj = _get_rat_infomodel_obj(rat)
    rat_info = get_managed_objects_for_class(connection=connection, object_class_name=infomodel_obj)
    statuses = {stat_name: stat_value for stat_name, stat_value in rat_info[0]['parameters']['stateInfo'].items()}

    return statuses


