@log_input_and_output
def get_cells_dist_names_for_rmod(connection, cell_type, rmod_id):
    """
    !!!THIS METHOD DOES NOT SUPPORT CONFIGURATIONS WITH BOTH RMODS AND ASIRMODS!!!
    Gets both runtime and configuration dist_names for all cells in given RAT and RMOD/ASIRMOD id
    :param connection: AdminConnection object or if used, string name alias
    :type connection: AdminConnection or str
    :param cell_type: cell type of given RAT: "lte", "wcdma", "gsm", "nr"
    :type cell_type: str
    :param rmod_id: RMOD/ASIRMOD runtime ID
    :type rmod_id: str or int
    :raises CellIdsNotFound: when cell ids for given cell type and rmod_id are not found
    :raises CellInfoNotFound: when for one of the cells distnames couldn't be found for provided rmod_id
    :return: list of dicts with runtime and configuration dist_names
             e.g. [{"run_time": "/MRBTS-1/RUN/TIME/CELL_R-1", "configuration": "/MRBTS-1/CFG/CELL-1"}]
    :rtype: list of dict
    """
    cells_dist_names = []
    translated_rmod = _translate_rmod_indexes_from_runtime(connection=connection)[int(rmod_id)]
    cell_ids = _get_cell_ids_for_ru_of_type(connection=connection, rmod_id=translated_rmod, cell_type=cell_type)

    if not cell_ids:
        raise CellIdsNotFound(f"There are no {cell_type} cells configured for RU ID: {translated_rmod}")

    for cell_id in cell_ids:
        cells_dist_names.append(_get_dist_names_for_specific_cell(connection=connection,
                                                                  cell_type=cell_type,
                                                                  cell_id=cell_id)
                                )

    return cells_dist_names


