def get_rmod_ids_for_rat(connection, rat_type="nr"):
    """
    !!!THIS METHOD DOES NOT SUPPORT CONFIGURATIONS WITH BOTH RMODS AND ASIRMODS!!!
    Gets RMOD/ASIRMOD IDs for specific RAT type via admin.
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param rat_type: one of following RAT types: "lte", "wcdma", "gsm", "nr" (5G). Default: "nr".
    :type rat_type: str
    :return: RMOD/ASIRMOD runtime ids for provided rat type
    :rtype: list (without duplicates) of RMOD/ASIRMOD IDs for particular rat type
    """
    rmod_ids = []

    cell_ids = _get_cell_ids_from_specific_rat(connection=connection, cell_type=rat_type)
    for cell_id in cell_ids:
        rmods_for_cell = _get_rmod_ids_for_cell_id(connection=connection, cell_id=cell_id, cell_type=rat_type)
        if isinstance(rmods_for_cell, list):
            rmod_ids = rmod_ids + rmods_for_cell
        else:
            rmod_ids.append(rmods_for_cell)

    rmod_ids = list(set(rmod_ids))

    return [int(rmod_id) for rmod_id in rmod_ids]


def is_cell_shared(connection, cell_id, cell_type):
    """
    !!!THIS METHOD DOES NOT SUPPORT CONFIGURATIONS WITH BOTH RMODS AND ASIRMODS!!!
    Determines whether cell of given cell_type and cell_id is shared between more than one RMOD/ASIRMOD.
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param cell_type: Cell type of given RAT: "lte", "wcdma", "gsm", "nr"
    :type cell_type: str
    :param cell_id: ID of cell
    :param cell_id: int or str
    :return: info whether given cell is shared between more than one RMOD/ASIRMOD
    :rtype: bool
    """
    return _is_cell_shared(connection=connection, cell_id=cell_id, cell_type=cell_type)


def is_supercell(connection, configuration_distname):
    """
    Determines if cell with given configuration_distname is a supercell.
    Only NR cells can be supercells.
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param configuration_distname: configuration distname of checked cell
    :type configuration_distname: str
    :return: True if cell is supercell, False if not
    :rtype: bool
    """
    cell_type = _get_cell_type_from_distname(distname=configuration_distname)
    if cell_type != "nr":
        return False

    runtime_distname = _translate_cell_config_distname_to_runtime_distname(cell_config_distname=configuration_distname,
                                                                           connection=connection)
    return _is_supercell(connection=connection, runtime_distname=runtime_distname)


