@log_input_and_output
def is_any_rmod_shared(connection, rmod_ids):
    """
    Determines whether any RMOD within given rmod_ids is configured
    to work in shared mode.
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param rmod_ids: IDs of radio modules
    :type rmod_ids: list(str)
    :return: True if shared, False if not
    :rtype: bool
    """
    is_shared = []
    for rmod_id in rmod_ids:
        is_shared.append(_is_rmod_shared(connection=connection, rmod_id=rmod_id))

    return any(is_shared)


def is_rmod_shared(connection, rmod_id):
    """
    Determines whether RMOD with given rmod_id is configured
    to work in shared mode.
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param rmod_id: ID of radio module
    :type rmod_id: str or int
    :return: True if shared, False if not
    :rtype: bool
    """
    return _is_rmod_shared(connection=connection, rmod_id=rmod_id)


