def get_cells_not_shared_with_locked_rmod(connection, cell_distnames):
    """
    !!!THIS METHOD DOES NOT SUPPORT CONFIGURATIONS WITH BOTH RMODS AND ASIRMODS!!!
    Checks each of the cells given in cell_distnames and
    returns those which are not shared with currently locked RMOD/ASIRMOD.
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param cell_distnames: list of cell distnames to check
    :type cell_distnames: list(str)
    :returns: list of cells not shared with currently locked RMOD/ASIRMOD
    :rtype: list(str)
    """
    return [cell_distname for cell_distname in cell_distnames if not _is_cell_shared_with_locked_rmod(
        connection=connection, cell_id=cell_distname.split("/")[-1].split("-")[-1])]


@log_input_and_output
def get_configuration_distnames_of_not_shared_cells_for_rmod(connection, rmod_id):
    """
    Returns configuration distnames of not shared cells for given RMOD id.
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param rmod_id: configuration RMOD ID
    :type rmod_id: str or int
    :return: list of configuration distnames of not shared cells for given RMOD id, e.g.:
             ['MRBTS-50521/NRBTS-50521/NRCELL-1', 'MRBTS-50521/LNBTS-50521/LNCEL-1']
    :rtype: list of str
    """
    return [cell_distname for cell_distname in _get_configuration_distnames_of_all_cells_for_rmod(
        rmod_id=rmod_id, connection=connection) if not _is_cell_shared(
        connection=connection, cell_id=cell_distname.split("-")[-1],
        cell_type=_get_cell_type_from_distname(distname=cell_distname))]


