def _is_cell_shared_with_locked_rmod(connection, cell_id):
    locked_rmods = _get_all_locked_rmods(connection=connection)

    for rmod in locked_rmods:
        cells_per_rat = _get_cell_ids_for_ru_for_all_rats(connection=connection, rmod_id=rmod)
        for rat, cells in cells_per_rat.items():
            for cell in cells:
                if int(cell_id) == int(cell):
                    return True

    return False


@log_input_and_output
def _get_configuration_distnames_of_all_cells_for_rmod(rmod_id, connection):
    """
    Gets configuration distname of all cells created on provided RMOD ID.

    :param rmod_id:  configuration RMOD ID.
    :type rmod_id: str or int
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :return: list of configuration distnames of all cells for given RMOD ID e.g.: ["/MRBTS-1/NRBTS-1/NRCELL-1, /MRBTS-1/NRBTS-1/NRCELL-2"]
    :rtype: list of str
    """
    all_cells_conf_distname = _get_all_cells_distnames(connection=connection)
    cell_ids_for_all_rmods = _get_cells_for_all_rmods(connection=connection)

    distnames_of_cells_for_rmod = _get_distnames_of_cells_for_given_rmod(
        cell_ids_for_all_rmods=cell_ids_for_all_rmods, all_cells_distnames=all_cells_conf_distname,
        rmod_id=rmod_id)

    return distnames_of_cells_for_rmod


def _is_rmod_shared(connection, rmod_id):
    adm = admin()
    rmods_info = adm.get_managed_objects(class_name="RMOD_A", connection=connection)

    for rmod_info in rmods_info:
        if "RMOD_A-{}".format(rmod_id) in rmod_info["distName"]:
            try:
                return rmod_info["parameters"]["actSharedRUIndControl"]
            except KeyError:
                return False


def _get_all_locked_rmods(connection):
    rmod_statuses = _get_statuses_of_all_rmods(connection=connection)
    return [rmod for rmod, statuses in rmod_statuses.items() if statuses["administrativeState"] == "Locked"]


@log_input_and_output
def _get_rmod_ids_for_cell_id(connection, cell_id, cell_type="nr", rmod_distname_type="internal"):
    rmods_cell_ids = _get_cell_ids_for_all_rus(connection=connection, cell_type=cell_type)

    rmod_ids = []
    for rmod_id, cell_ids in rmods_cell_ids.items():
        if int(cell_id) in cell_ids:
            if rmod_distname_type == "internal":
                rmod_ids.append(str(_translate_rmod_indexes_to_runtime(connection=connection)[int(rmod_id)]))
            if rmod_distname_type == "configuration":
                rmod_ids.append(int(rmod_id))

    if not rmod_ids:
        raise RmodIdForCellIdNotFound(f"Related rmod ID couldn't be found for {cell_type} cell ID: {cell_id}")

    if len(rmod_ids) == 1:
        return rmod_ids[0]

    return rmod_ids


