@log_input_and_output
def translate_rmod_distname_to_runtime(rmod_distname, connection):
    """
    !!!THIS METHOD DOES NOT SUPPORT CONFIGURATIONS WITH BOTH RMODS AND ASIRMODS!!!
    Translates configured distName of RMOD/ASIRMOD to runtime distName.
    :param rmod_distname: configured distName of RMOD/ASIRMOD
    :type rmod_distname: str
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :return: runtime distName of RMOD/ASIRMOD
    :rtype: str
    """
    rmod_id = re.search(r'RMOD-(\d+)', rmod_distname).group(1)
    translated_rmods = _translate_rmod_indexes_to_runtime(connection=connection)
    return _get_runtime_distname_for_rmod(connection, runtime_rmod_id=translated_rmods[int(rmod_id)])


@log_input_and_output
def translate_rmod_distname(rmod_distname, output_distname_type, connection):
    """
    Translates distName of RMOD/ASIRMOD to desired distName type.
    :param rmod_distname: distName of RMOD/ASIRMOD
    :type rmod_distname: str
    :param output_distname_type: type of desired output RMOD/ASIRMOD distName: `configuration`, `runtime`, `internal`
    :type output_distname_type: str
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :return: distName of RMOD/ASIRMOD defined by `output_distname_type` param
    :rtype: str
    """
    for rmod in _get_rmods_info(connection=connection):
        for distname_type, distname in rmod['id'].items():
            if distname == rmod_distname and distname_type != output_distname_type:
                return rmod['id'][output_distname_type]
            if distname == rmod_distname and distname_type == output_distname_type:
                raise TranslatedDistNameIsTheSame(
                    f"Translated distname is equal to the one provided as input! "
                    f"{rmod_distname}=={rmod['id'][output_distname_type]}"
                )


