@log_input_and_output
def get_independent_rmods_in_chain(connection, runtime_rmod_id):
    """
    !!!THIS METHOD DOES NOT SUPPORT CONFIGURATIONS WITH BOTH RMODS AND ASIRMODS!!!
    Gets RMODs/ASIRMODs in chain independent of RMOD/ASIRMOD with provided runtime ID.
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param runtime_rmod_id: runtime ID of RMOD/ASIRMOD
    :type runtime_rmod_id: Union[int, str]
    :return: independent runtime RMODs/ASIRMODs in chain as a list, e.g. ['RMOD_R-2', 'RMOD_R-4']
    :rtype: list
    """
    cablink_connections = {rmod: connections for rmod, connections in _get_cablink_connections(connection).items()
                           if "RMOD" in rmod}
    try:
        all_chains = _get_chains_for_all_rmods(cablink_connections)[f"RMOD_R-{runtime_rmod_id}"]
        all_chains.remove(f"RMOD_R-{runtime_rmod_id}")
    except KeyError:
        all_chains = _get_chains_for_all_rmods(cablink_connections)[f"ASIRMOD_R-{runtime_rmod_id}"]
        all_chains.remove(f"ASIRMOD_R-{runtime_rmod_id}")
    return all_chains


@log_input_and_output
def get_radios_with_priority_in_chain(connection):
    """
    Returns list of most important RMODs and ASIRMODs in chains ordered from the most to the least important. Radios ending the chain
    are not included.
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :return: list of most important RMODs and ASIRMODs in chains ordered from the most to the least important.
    :rtype: list
    """
    cablink_connections = {rmod: connections for rmod, connections in _get_cablink_connections(connection).items()
                           if "RMOD" in rmod}
    all_chains = _get_chains_for_all_rmods(cablink_connections)

    subchains = {slave: [master for master in masters if master != slave]
                 for slave, masters in all_chains.items() if masters != [slave]}

    output = []
    for slave, masters in subchains.items():
        for master in masters:
            if slave in output and master not in output:
                output.insert(output.index(slave), master)
            elif master not in output:
                output.append(master)

    return output


