def reset_rmod_in_separate_process(connection, runtime_rmod_id, connection_host):
    """
    !!!THIS METHOD DOES NOT SUPPORT CONFIGURATIONS WITH BOTH RMODS AND ASIRMODS!!!
    Resets RMOD/ASIRMOD unit in separate process via admin.
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param runtime_rmod_id: runtime ID for RMOD/ASIRMOD, i.e.: 2
    :type runtime_rmod_id: Union[int, str]
    :param connection_host: HTTP connection host
    :type connection_host: str
    """
    adm = admin()
    dist_name = _get_runtime_distname_for_rmod(connection=connection, runtime_rmod_id=runtime_rmod_id)
    adm.connect_to(bts_host=connection_host,
                   name="rmod_reset")
