def is_rmod_dss(connection, rmod_id):
    """
    !!!THIS METHOD DOES NOT SUPPORT CONFIGURATIONS WITH BOTH RMODS AND ASIRMODS!!!
    Checks whether dssNrCellId is present for RMOD/ASIRMOD.
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param rmod_id: RMOD/ASIRMOD config id
    :type rmod_id: Union[int, str]
    :return: True if radio unit is DSS, False otherwise
    :rtype: bool
    """
    nr_cell_ids = _get_cell_ids_for_ru_of_type(connection=connection, rmod_id=rmod_id, cell_type="nr")
    dss_cell_ids = _get_global_dss_nr_cell_ids(connection=connection)
    for dss_cell in dss_cell_ids:
        if dss_cell in nr_cell_ids:
            return True
    return False


@log_input_and_output
def get_partner_cell_if_dss_mode(cell_id, cell_type, connection):
    """
    Checks whether cell is in DSS mode and if 'True' return partner cell.
    Function supports only cells in 'NR-LTE' DSS mode.
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param cell_id: cell id
    :type cell_id: Union[int, str]
    :param cell_type: cell type e.g. "nr", "lte"
    :type cell_type: str
    :return: dict with partner configured_cell_id and cell_type, e.g. {'1': {'partner_cell_id': '5', 'cell_type': 'lte'}
             if cell is not in DSS mode return empty dict.
    :rtype: dict[str, str]
    """
    name = {'nr': {'cell_obj': 'NRCELL_A', 'dss': 'NRDSSLTE_A', 'param_cell_id': 'lcrId'},
            'lte': {'cell_obj': 'LNCEL_A', 'dss': 'DSSNR_A', 'param_cell_id': 'dssNrCellId'}}

    cell_type_info = name[cell_type]
    inf_a_cells = _get_managed_objects_for_class(connection=connection, object_class_name=cell_type_info['cell_obj'])
    inf_a_dss = _get_managed_objects_for_class(connection=connection, object_class_name=cell_type_info['dss'])

    for cell in inf_a_cells:
        cell_params = cell['parameters']
        if int(cell_params['lcrId']) == int(cell_id):
            if cell_params['lteNrDssMode'] != 'none':
                name_a = cell['distName'].split('/')[-1]
                for dss in inf_a_dss:
                    if name_a in dss['distName']:
                        return {'partner_cell_id': dss['parameters'][cell_type_info['param_cell_id']],
                                'cell_type': 'nr' if cell_type == 'lte' else 'lte'}
            else:
                break
    return {}


