@log_input_and_output
def _get_runtime_smod_id_for_connected_rmod(runtime_rmod_id, connection):
    adm = admin()
    cablink_objects = adm.get_managed_objects(connection=connection, class_name="CABLINK_R")

    if _check_if_rmod_endpoint_exists_in_cablink_objects(cablink_objects):
        rmod_link_objects = cablink_objects
    else:
        rmod_link_objects = adm.get_managed_objects(connection=connection, class_name="LOGLINK_R")

    primary_link_device, secondary_link_device = _get_primary_secondary_link_device_connected_to_rmod(rmod_link_objects,
                                                                                                      runtime_rmod_id)

    if primary_link_device is None or "SMOD_EXT_R" in primary_link_device:
        device_connected_with_rmod = secondary_link_device
    else:
        device_connected_with_rmod = primary_link_device

    if device_connected_with_rmod is None:
        raise ObjectNotFound(f"Not found any internal object connected to RMOD runtime ID: {runtime_rmod_id}")

    if "SMOD_R-" in device_connected_with_rmod:
        return device_connected_with_rmod.split("-")[-1]

    smod_runtime = _get_device_connected_to_bbmod(cablink_objects, device_connected_with_rmod)

    return smod_runtime.split("-")[-1]


@log_input_and_output
def _get_runtime_smod_id_for_connected_bbmod(runtime_bbmod_id, connection):
    adm = admin()
    cablink_objects = adm.get_managed_objects(connection=connection, class_name="CABLINK_R")

    for cablink_obj in cablink_objects:
        if f"BBMOD_R-{runtime_bbmod_id}" in cablink_obj['parameters']['secondEndpointDN']:

            if "SMOD_R-" in cablink_obj['parameters']['firstEndpointDN']:
                smod_runtime_distname = cablink_obj['parameters']['firstEndpointDN']
                return smod_runtime_distname.split("-")[-1]

    raise ObjectNotFound(f"BBMOD_R-{runtime_bbmod_id} was not found in runtime cablink objects: {cablink_objects}")


def _check_if_rmod_endpoint_exists_in_cablink_objects(cablink_objects):
    for cablink_obj in cablink_objects:
        if "RMOD_R-" in cablink_obj['parameters']['secondEndpointDN']:
            return True

    return False


@log_input_and_output
def _get_primary_secondary_link_device_connected_to_rmod(cablink_objects, runtime_rmod_id):
    primary_link_device, secondary_link_device = None, None
    for cablink_obj in cablink_objects:
        if f"/RMOD_R-{runtime_rmod_id}" in cablink_obj['parameters']['secondEndpointDN']:
            if cablink_obj['parameters']['linkModeSynchronization'] is True:
                primary_link_device = cablink_obj['parameters']['firstEndpointDN'].split("/")[-1]
            else:
                secondary_link_device = cablink_obj['parameters']['firstEndpointDN'].split("/")[-1]

    return primary_link_device, secondary_link_device


@log_input_and_output
def _get_device_connected_to_bbmod(cablink_objects, runtime_bbmod):
    for cablink_obj in cablink_objects:
        if f"/{runtime_bbmod}" in cablink_obj['parameters']['secondEndpointDN']:
            return cablink_obj['parameters']['firstEndpointDN'].split("/")[-1]

    raise ObjectNotFound(f"Object firstEndpointDN cannot be found for BBMOD object: {runtime_bbmod}")


@log_input_and_output
def _check_active_role_of_smod(runtime_smod_id, connection):
    adm = admin()
    bts_info = adm.get_bts_info(connection=connection)

    for smod_obj in bts_info['systemModules']:
        if f"/SMOD_R-{runtime_smod_id}" in smod_obj['id']['runtime']:
            return smod_obj.get('activeRole', 'Primary')

    raise ObjectNotFound(f"Object SMOD_R-{runtime_smod_id} cannot be found in current configuration")


