@log_input_and_output
def is_iot_cell(connection, cell_type, cell_id):
    """
    Determines whether cell of given cell_type and cell_id is from NB-IoT cell technology.
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param cell_type: Cell type of given RAT: "lte", "wcdma", "gsm", "nr"
    :type cell_type: str
    :param cell_id: ID of cell
    :param cell_id: int
    :return: info whether given cell is of NB-IoT technology
    :rtype: bool
    """
    iot_technologies = ["NB-IoT-FDD"]
    cell_technology = _get_cell_technology(
        connection=connection, cell_type=cell_type, cell_id=cell_id
    )

    if cell_technology in iot_technologies:
        return True
    return False


@log_input_and_output
def get_narrow_band_iot_mode_for_lte_cell_id(cell_id, connection):
    """
    Gets narrow band IoT mode for particular lte cell id.

    :param cell_id: globalCellId of lte cell
    :type cell_id: int or str
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :return: mode of lte narrow band: "disabled", "standalone", "inband" or "guardband"
    :rtype: str
    :raises CellNotFound: when provided cell id is not found in current configuration.
    """
    adm = admin()
    cells_infos = adm.get_cells_info(connection=connection, cell_type="lte")

    for cell in cells_infos:
        if cell['globalCellId'] == int(cell_id):
            return cell['narrowbandIotMode']
    raise CellIdsNotFound(f"LTE cell with globalCellId: {cell_id} is not found in current configuration")


