@log_input_and_output
@raise_when_output_is_empty
def get_statuses_of_all_smods(connection, timeout=60):
    """
    Get all statuses of all SMODs

    :param connection: AdminConnection object or, if used, string name alias
    :type connection: AdminConnection or str
    :param timeout: timeout for positive procedure result
    :return: dictionary with SMOD's distName as key and SMOD's statuses as value
    """
    adm = admin()
    smods_status = {}
    system_module_info = adm.get_bts_info(connection=connection, timeout=timeout)['systemModules']
    for system in system_module_info:
        smod_distname = system['id']['configuration']
        smod_status = system['status']
        smods_status[smod_distname] = smod_status
    return smods_status


@log_input_and_output
def get_statuses_of_all_gnss(connection, timeout=60):
    """
    Get statuses of all configured GNSS

    :param connection: AdminConnection object or, if used, string name alias
    :type connection: AdminConnection or str
    :param timeout: timeout for positive procedure result
    :type timeout: int
    :return: dictionary with GNSS' name as key and GNSS' statuses as value
    """
    adm = admin()
    bts_info = adm.get_bts_info(connection=connection, timeout=timeout)
    is_sync_via_gnss = '1pps/ToD from external GNSS receiver' in _get_bts_sync_input_types(connection=connection)

    if 'gnsse' not in bts_info.keys() or not bts_info['gnsse'] or not is_sync_via_gnss:
        raise GnssNotConfigured('Cannot get GNSS statuses because it does not exist in the configuration')

    all_gnss_statuses = {}
    for gnsse in bts_info['gnsse']:
        _gnss_status = gnsse['stateInfo']
        gnss_status = {'availabilityStatus': _gnss_status.get('availabilityStatus'),
                       'operationalState': _gnss_status.get('operationalState'),
                       'administrativeState': _gnss_status.get('administrativeState')}
        all_gnss_statuses[gnsse['name']] = gnss_status
    return all_gnss_statuses


@log_input_and_output
def get_bbmods_distnames(connection):
    """
    Get distNames of all configured BBMODs
    :param connection: AdminConnection object or, if used, string name alias
    :type connection: AdminConnection or str
    :return: { 1: { 'configured': '', 'runtime': ''},
               2: { 'configured': '', 'runtime': ''},
               ...
             }
    """
    adm = admin()
    bbmods_info = adm.get_bts_info(connection=connection, timeout=60)['basebandModules']
    bbmods_distname = dict()
    for bbmod_info in bbmods_info:
        try:
            _bbmod_id = int(bbmod_info['id']['configuration'].split('-')[-1])
            bbmods_distname[_bbmod_id] = {
                'configured': bbmod_info['id']['configuration'],
                'runtime': bbmod_info['id']['internal']}

        except KeyError as e:
            missing_key = e.args[0]
            if missing_key == 'configuration' and bbmod_info['status']['usageState'].lower() == 'idle':
                log_warning(f"Looks like BBMOD_R-{bbmod_info['id']['internal'].split('-')[-1]} is not commissioned and "
                            f"will be omitted in the test. Check if this is appropriate behavior")
                continue
            raise

    return bbmods_distname


@log_input_and_output
def get_cablinks_info(connection):
    """
    Get information about all configured cablinks
    :param connection: AdminConnection object or, if used, string name alias
    :type connection: AdminConnection or str
    :return: dict with cablinks distNames as keys and cablinks info as values
    """
    cablinks = _get_cablinks_details(connection=connection)
    cablinks_info = {}
    for cablink in cablinks:
        cablink_distname = cablink['id']['configuration']
        log_result(cablink_distname)
        cablink_params = _get_parameters_by_distname(connection=connection, dist_name=cablink_distname)
        cablinks_info[cablink_distname] = cablink_params
    return cablinks_info


