@log_input_and_output
def get_primary_rmods_for_bbmod(bbmod_runtime_distname, connection):
    """
    Gets RMODs and ASIRMODs runtime distnames that are connected via primary link to given BBMOD within
    cablinks and loglinks connections.
    :param bbmod_runtime_distname: runtime distname of BBMOD
    :type bbmod_runtime_distname: str
    :param connection: AdminConnection object or, if used, string name alias
    :type connection: AdminConnection or str
    :return: list of runtime distnames of RMODs and ASIRMODs
    :rtype: list
    """
    primary_rmods_cablinks = _get_primary_rmods_for_bbmod_cablink_connections(
        bbmod_runtime_distname=bbmod_runtime_distname, connection=connection)
    primary_rmods_loglinks = _get_primary_rmods_for_bbmod_loglink_connections(
        bbmod_runtime_distname=bbmod_runtime_distname, connection=connection)

    return list(set(primary_rmods_cablinks + primary_rmods_loglinks))


@log_input_and_output
def get_bbmod_serial_number(connection, bbmod_id):
    """
    Gets BBMOD serial number
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param bbmod_id: BBMOD configuration ID
    :type bbmod_id: str or int
    :return: serial number of BBMOD
    :rtype: str
    :raises ParameterDoesNotExist when serial number of BBMOD with provided id could not be found.
    """
    for elem in _get_bbmods_info(connection=connection):
        if elem['id'].get('configuration'):
            if elem['id']['configuration'].split('-')[-1] == str(bbmod_id):
                return elem['serialNumber']
        else:
            log_suppression(f"BBMOD_R-{elem['id']['internal'].split('-')[-1]} is not commissioned")
            continue

    raise ParameterDoesNotExist(f"Serial number of BBMOD with ID: {bbmod_id} could not be found")


def get_runtime_bbmod_id(connection, bbmod_id):
    """
    Gets runtime BBMOD ID based on provided BBMOD's configuration ID
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param bbmod_id: BBMOD configuration ID
    :type bbmod_id: str
    :return: runtime id of BBMOD
    :rtype: str
    :raises ParameterDoesNotExist when runtime id of BBMOD with provided id could not be found.
    """
    for elem in _get_bbmods_info(connection=connection):
        if elem['id'].get('configuration'):
            if elem['id']['configuration'].split('-')[-1] == str(bbmod_id):
                return elem['id']['runtime'].split('-')[-1]
        else:
            log_suppression(f"BBMOD_R-{elem['id']['internal'].split('-')[-1]} is not commissioned")
            continue

    raise ParameterDoesNotExist(f"Runtime ID of BBMOD with ID: {bbmod_id} could not be found")


@log_input_and_output
def _get_primary_rmods_for_bbmod_cablink_connections(bbmod_runtime_distname, connection):
    cablinks_info = _get_parameters_for_all(connection=connection, hw_type="CABLINK")
    primary_cablinks = _get_primary_cablinks(connection=connection, distname_type='runtime')

    primary_rmods = []
    for info in cablinks_info:
        for primary_cablink in primary_cablinks:
            connections = [info['secondEndpointDN'], info['firstEndpointDN']]
            if info['id'].split("/")[-1] == primary_cablink.split("/")[-1] and bbmod_runtime_distname in connections:
                primary_rmods.extend([rmod for rmod in connections if "RMOD" in rmod])

    return primary_rmods


@log_input_and_output
def _get_primary_rmods_for_bbmod_loglink_connections(bbmod_runtime_distname, connection):
    loglinks_info = _get_managed_objects_for_class(object_class_name="LOGLINK_R", connection=connection)

    return [loglink_info['parameters']['secondEndpointDN'] for loglink_info in loglinks_info if bbmod_runtime_distname
            in loglink_info['parameters']['firstEndpointDN'] and "RMOD" in
            loglink_info['parameters']['secondEndpointDN']]


@log_input_and_output
def get_distnames_of_rmods_connected_to_bbmod(connection, bbmod_id=1, type='runtime'):
    """
    !!!THIS METHOD DOES NOT SUPPORT CONFIGURATIONS WITH BOTH RMODS AND ASIRMODS!!!
    Get distNames of all RMODs/ASIRMODs connected to given BBMOD
    :param connection: AdminConnection object or, if used, string name alias
    :type connection: AdminConnection or str
    :param bbmod_id: configured BBMOD id
    :type bbmod_id: int or str
    :param type: type of RMOD/ASIRMOD distName: configured or runtime
    :type type: str
    :return: dict with RMODs/ASIRMODs IDs as keys and RMODs/ASIRMODs distNames as values
    """
    cablinks_info = get_cablinks_info(connection=connection)
    bbmods_distname = get_bbmods_distnames(connection=connection)
    fronthaul_switch_rmods = get_rmods_connected_through_fronthaul_switch(connection=connection)
    rmods_connected_to_bbmod = _get_config_distnames_of_rmods_connected_to_bbmod(
        bbmod_id=int(bbmod_id),
        cablinks_info=cablinks_info,
        bbmods_distname=bbmods_distname,
        fronthaul_switch_rmods=fronthaul_switch_rmods)
    if type == 'configured':
        log_result("RMODs connected to BBMOD-{} (configured): {}".format(bbmod_id, rmods_connected_to_bbmod))
        return rmods_connected_to_bbmod
    if type == 'runtime':
        rmods_connected_to_bbmod_runtime = _translate_rmod_config_distnames_to_runtime_distnames(
            connection=connection,
            rmod_config_distnames=rmods_connected_to_bbmod)
        log_result("RMODs connected to BBMOD-{} (runtime): {}".format(bbmod_id, rmods_connected_to_bbmod_runtime))
        return rmods_connected_to_bbmod_runtime
    else:
        raise ValueError('Wrong type "{}" - available types configured or runtime'.format(type))


@log_input_and_output
def reset_rat(connection, rat, reset_type, graceful_cell_shutdown, timeout):
    """
    Resets RAT via admin.
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param rat: RAT name - NR, LTE, WCDMA or GSM
    :type rat: str
    :param reset_type: type of reset, e.g. "Soft", "Hard"
    :type reset_type: str
    :param graceful_cell_shutdown: flag for graceful cell shutdown
    :type graceful_cell_shutdown: bool
    :param timeout: timeout for reset
    :type timeout: Union[int,str]
    """
    adm = admin()
    adm.rat_reset(connection=connection, rat_type=rat.upper(), reset_type=reset_type.lower().capitalize(),
                  graceful_cell_shutdown=graceful_cell_shutdown, timeout=timeout)


@log_input_and_output
def _get_config_distnames_of_rmods_connected_to_bbmod(bbmod_id, cablinks_info, bbmods_distname, fronthaul_switch_rmods):
    """
    Get configured distNames of all RMODs connected to given BBMOD
    :param bbmod_id: configured BBMOD id
    :type bbmod_id: int
    :param cablinks_info: dict with cablinks distNames as keys and cablinks info as values
    :type cablinks_info: dict
    :param bbmods_distname: dictionary with BBMODs' configured and runtime as a key and distNames as a value
    :type bbmods_distname: dict
    :param fronthaul_switch_rmods: dictionary with fronthaul switch distNames as keys and RMODs distNames as values
    :type fronthaul_switch_rmods: dict
    :return: dict with RMODs IDs as keys and RMODs distNames as values
    """
    rmods_connected_to_bbmod = {}
    for cablink_distname in cablinks_info.keys():
        if bbmods_distname[bbmod_id]['configured'] in cablinks_info[cablink_distname]['firstEndpointDN']:
            connected_device_distname = cablinks_info[cablink_distname]['secondEndpointDN']
            if connected_device_distname in fronthaul_switch_rmods.keys():
                rmods_distnames = fronthaul_switch_rmods[connected_device_distname]
                for rmod in rmods_distnames:
                    rmod_id = rmod.split('RMOD-')[1]
                    rmods_connected_to_bbmod.update({int(rmod_id): rmod})
            else:
                if 'RMOD' in connected_device_distname:
                    rmod_id = connected_device_distname.split('RMOD-')[1]
                    rmods_connected_to_bbmod.update({int(rmod_id): connected_device_distname})
    return rmods_connected_to_bbmod


@log_input_and_output
def _translate_rmod_config_distnames_to_runtime_distnames(connection, rmod_config_distnames):
    """
    Translate IDs and distNames of RMODs from configured to runtime
    :param connection: AdminConnection object or, if used, string name alias
    :type connection: AdminConnection or str
    :param rmod_config_distnames: dictionary with RMODs' configured IDs as keys and
                                  RMODs' configured distNames as values
    :type rmod_config_distnames: dict
    :return: dict with RMODs' runtime IDs as keys and RMODs' runtime distNames as values
    """
    rmods_runtime_distnames = {}
    for rmod_id, rmod_distname in rmod_config_distnames.items():
        runtime_distname = translate_rmod_distname_to_runtime(rmod_distname=rmod_distname, connection=connection)
        runtime_rmod_id = translate_rmod_indexes_to_runtime(connection=connection)[int(rmod_id)]
        rmods_runtime_distnames.update({runtime_rmod_id: runtime_distname})
    return rmods_runtime_distnames


@log_input_and_output
def get_rmods_connected_through_fronthaul_switch(connection):
    rmods_connected_to_fronthaul_switch = {}
    cablinks_info = get_cablinks_info(connection=connection)
    for cablink_info in cablinks_info.values():
        if 'FHS' in cablink_info['firstEndpointDN'] and 'RMOD' in cablink_info['secondEndpointDN']:
            fhs_distname = cablink_info['firstEndpointDN']
            rmod_distname = cablink_info['secondEndpointDN']
            if fhs_distname not in rmods_connected_to_fronthaul_switch:
                rmods_connected_to_fronthaul_switch[fhs_distname] = [rmod_distname]
            elif rmod_distname not in rmods_connected_to_fronthaul_switch[fhs_distname]:
                rmods_connected_to_fronthaul_switch[fhs_distname].append(rmod_distname)
    return rmods_connected_to_fronthaul_switch


@log_input_and_output
def get_bbmod_ids_for_all_rmods_links(connection):
    """
    !!!THIS METHOD DOES NOT SUPPORT CONFIGURATIONS WITH ASIRMODS!!!
    Gets BBMOD configuration IDs for all links for configured RMODs.
    :param connection: AdminConnection object or, if used, string name alias
    :type connection: AdminConnection or str
    :return: dictionary containing bbmods link configuration with RMOD ID (int type) as key and dictionary with BBMOD's
             IDs list (int type) related to link mode as value, e.g.:
             {1: {'synchronization': [1], 'data': [2], 'configuration': [1]},
              2: {'synchronization': [1], 'data': [1, 2], 'configuration': []},
              3: {'synchronization': [2], 'data': [2], 'configuration': [2]},
              4: {'synchronization': [3], 'data': [1], 'configuration': [3]}}
    :rtype: dict(int, dict(str, list[int]))
    """

    rmod_config_ids = get_rmod_indexes(connection=connection, dist_name_type="configuration")

    adm = admin()
    bbmods_info = adm.get_bts_info(connection=connection, timeout=60)['basebandModules']

    bbmod_connections = {}
    for rmod_id in rmod_config_ids:
        bbmod_connections[rmod_id] = {"synchronization": [], "data": [], 'configuration': []}

        runtime_bbmods_synchro = _get_runtime_bbmod_object_name_for_connected_rmod(rmod_id=rmod_id,
                                                                                   link_mode='synchronization',
                                                                                   connection=connection)
        runtime_bbmods_data = _get_runtime_bbmod_object_name_for_connected_rmod(rmod_id=rmod_id,
                                                                                link_mode='data',
                                                                                connection=connection)
        runtime_bbmods_configuration = _get_runtime_bbmod_object_name_for_connected_rmod(rmod_id=rmod_id,
                                                                                         link_mode='configuration',
                                                                                         connection=connection)

        for bbmod in bbmods_info:
            if bbmod['id'].get('configuration'):
                bbmod_config_id = int(bbmod['id']['configuration'].split("-")[-1])
            else:
                log_suppression(f"BBMOD_R-{bbmod['id']['internal'].split('-')[-1]} is not commissioned")
                continue

            bbmod_runtime_object_name = bbmod['id']['runtime'].split("/")[-1]

            if bbmod_runtime_object_name in runtime_bbmods_synchro:
                bbmod_connections[rmod_id]["synchronization"].append(bbmod_config_id)
            if bbmod_runtime_object_name in runtime_bbmods_data:
                bbmod_connections[rmod_id]["data"].append(bbmod_config_id)
            if bbmod_runtime_object_name in runtime_bbmods_configuration:
                bbmod_connections[rmod_id]["configuration"].append(bbmod_config_id)

    return bbmod_connections


@log_input_and_output
def get_rmod_ids_by_link_modes_for_bbmod_ids(bbmod_ids, connection='admin'):
    """
    !!!THIS METHOD DOES NOT SUPPORT CONFIGURATIONS WITH ASIRMODS!!!
    Gets RMODs configuration IDs connected to given BBMODs via all link modes: synchronization, data and configuration.
    :param bbmod_ids: configuration BBMOD ID(s) connected to RMODs, e.g.: 1.
    :type bbmod_ids: list of int or int
    :param connection: AdminConnection object or, if used, string name alias
    :type connection: AdminConnection or str
    :return: dict of rmod IDs related to given BBMODs with BBMOD configuration ID as key and dictionary with list of
    RMOD's IDs per particularlink mode (synchronization, data and configuration) with connection to given BBMODs as
    values, e.g: {1: {'synchronization': [], 'data': [1, 2], 'configuration': []},
                  2: {'synchronization': [1, 2], 'data': [1, 2], 'configuration': [1, 2]},
                  3: {'synchronization': [], 'data': [], 'configuration': []}}
    :rtype: dict(int, dict(str, list(int)))
    """
    rmod_ids_for_bbmods_dict = {}
    link_modes = ['synchronization', 'data', 'configuration']

    bbmod_ids = bbmod_ids if isinstance(bbmod_ids, list) else [bbmod_ids]

    bbmod_link_configuration = get_bbmod_ids_for_all_rmods_links(connection=connection)

    for bbmod_id in bbmod_ids:
        rmod_ids_for_bbmods_dict[bbmod_id] = {}

        for link_mode in link_modes:
            rmod_ids_for_bbmods_dict[bbmod_id][link_mode] = [
                rmod_id for rmod_id, bbmod_config in bbmod_link_configuration.items()
                if bbmod_id in bbmod_config[link_mode]]

    return rmod_ids_for_bbmods_dict


@log_input_and_output
def reset_bbmod(connection, bbmod_id=1):
    """
    Reset BBMOD and verify reset status
    :param connection: AdminConnection object or, if used, string name alias
    :type connection: AdminConnection or str
    :param bbmod_id: configured BBMOD id
    :type bbmod_id: int
    """
    adm = admin()
    bbmods_distname = get_bbmods_distnames(connection=connection)
    runtime_dist_name = bbmods_distname[bbmod_id]['runtime']
    status = adm.reset_unit(connection=connection, dist_name=runtime_dist_name, reset_type='Warm', timeout=1200)
    reset_status = [item['resultNode']['parameters']['status'] for item in status if 'resultNode' in item.keys()][0]
    if reset_status == 'Succeeded':
        log_result('BBMOD-{} reset performed successfully'.format(bbmod_id))
    else:
        raise BbmodResetError('BBMOD-{} reset has finished with status: {}'.format(bbmod_id, reset_status))


@log_input_and_output
def reset_bbmod_in_separate_process(connection, bbmod_id=1):
    """
    Resets BBMOD in separate process via admin.
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param bbmod_id: BBMOD id from configuration
    :type bbmod_id: int or str
    :return: process running in background
    """
    adm = admin()
    bbmods_distname = get_bbmods_distnames(connection=connection)
    runtime_dist_name = bbmods_distname[int(bbmod_id)]['runtime']
    task = adm.run_keyword_in_background(name='reset_unit',
                                         dist_name=runtime_dist_name,
                                         reset_type='Warm',
                                         timeout=120,
                                         connection=connection)
    log_step('BBMOD reset started')
    return task


@log_input_and_output
def get_statuses_of_all_bbmods(connection, timeout=30):
    """
    Get all statuses of all BBMODs

    :param connection: AdminConnection object or, if used, string name alias
    :type connection: AdminConnection or str
    :param timeout: timeout for positive procedure result
    :return: dictionary with BBMOD's configured ID as key and BBMOD's statuses as value
    """
    adm = admin()
    bbmods_info = adm.get_bts_info(connection=connection, timeout=timeout)['basebandModules']
    bbmods_status = dict()
    for bbmod_info in bbmods_info:
        try:
            _bbmod_id = int(re.search(r'BBMOD-(\d+)', bbmod_info['id']['configuration']).group(1))
        except KeyError:
            _bbmod_id = 'R_' + re.search(r'BBMOD_R-(\d+)', bbmod_info['id']['internal']).group(1)
        bbmods_status[_bbmod_id] = bbmod_info['status']
    return bbmods_status


