@log_input_and_output
def get_cells_statuses(cells_ids, cells_type, connection):
    """
    Gets statuses of cells with IDs provided in cells_ids
    :param cells_ids: ids of cells, e.g. [1, 3] or ["1", "3"]
    :type cells_ids: list of str or int
    :param cells_type: type of cells, can be "nr", "lte", "wcdma" or "gsm"
    :type cells_type: str
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :return: statuses for cells e.g. {"1": {"operationalState": 'enabled', "administrativeState": "unlocked",
                                            "usageState": "Idle", "blockingState": "Unblocked"},
                                      "2": {"operationalState": 'enabled', "administrativeState": "unlocked",
                                            "usageState": "Idle", "blockingState": "Blocked"}}
    :rtype: dict
    """
    all_cells_statuses = _get_statuses_of_all_cells(cells_type=cells_type, connection=connection)

    cells_statuses = {}
    for cell_id in cells_ids:
        if all_cells_statuses.get(str(cell_id)):
            cells_statuses[str(cell_id)] = all_cells_statuses[str(cell_id)]
        else:
            raise CellInfoNotFound("Could not find statuses for cell id {} of RAT {}".format(cell_id, cells_type))

    return cells_statuses


@log_input_and_output
def get_statuses_of_specific_cell(cell_id, cell_type, connection):
    """
    Gets statuses of all cells with given type
    :param cell_id: ids of cells, e.g. [1, 3]
    :type cell_id: Union[str, int]
    :param cell_type: type of cell, can be "nr", "lte", "wcdma" or "gsm"
    :type cell_type: str
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :return: statuses for cells with configuration cell id as key (str) and cell statuses as value (dict), e.g.:
              {"1": {"operationalState": 'enabled', "administrativeState": "unlocked",
                     "usageState": "Idle", "blockingState": "Unblocked"},
               "2": {"operationalState": 'enabled', "administrativeState": "unlocked",
                     "usageState": "Idle", "blockingState": "Blocked"}}
    :rtype: dict
    """
    adm = admin()
    id_param_name = _get_name_of_id_param_depending_on_cell_type(cell_type)
    bts_cells_info = adm.get_bts_info(connection=connection)["cells"][cell_type]

    for cell_info in bts_cells_info:
        cell_info_id = cell_info[id_param_name] if id_param_name is not None else \
            cell_info['id']['configuration'].split('-')[-1]
        if int(cell_info_id) == int(cell_id):
            return cell_info['status']

    raise CellInfoNotFound("Could not find statuses for cell id {} of RAT {}".format(cell_id, cell_type))


def get_statuses_of_cells_for_rmod(connection, rmod_internal_distname):
    """
    Gets statuses of cells connected to RMOD/ASIRMOD with given ID
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param rmod_internal_distname: internal distname of RMOD/ASIRMOD
    :type rmod_internal_distname: str
    :return: statuses for cells e.g. {
        "/MRBTS-1/RAT-1/RUNTIME_VIEW-4/MRBTS_R-4/LNBTS_R-50589/LNCEL_R-52": {
            "operationalState": 'enabled', "administrativeState": "unlocked",
            "usageState": "Idle", "blockingState": "Unblocked"
            },
        "/MRBTS-1/RAT-1/RUNTIME_VIEW-4/MRBTS_R-4/NRBTS_R-50589/NRCELL_R-302": {
            "operationalState": 'enabled', "administrativeState": "unlocked",
            "usageState": "Idle", "blockingState": "Blocked"}
        }
    :rtype: dict
    """
    bts_cells_info = _get_bts_info(connection=connection)["cells"]
    rmod_cell_mapping = get_cell_mapping_for_rmod(connection=connection, rmod_internal_distname=rmod_internal_distname)
    cells_statuses = {}

    for cell in rmod_cell_mapping:
        for cell_info in bts_cells_info[cell['RAT']]:
            if cell_info['id']['internal'] == cell['runtimeDistName']:
                cells_statuses[cell['runtimeDistName']] = cell_info['status']

    return cells_statuses


