@log_input_and_output
def get_cell_distname_for_cell_id(cell_id, cell_type, connection, distname_type='configuration'):
    """
    Returns configuration or runtime distname for particular cell ID and type.

    :param cell_id: ID of cell, "globalCellId" in case of nr or lte type, "cellId" in case of wcdma type
                    and "gsmSectorID" in case of gsm type
    :type cell_id: int or str
    :param cell_type: type of cell, can be "nr", "lte", "wcdma" or "gsm"
    :type cell_type: str
    :param distname_type: type of distame to return, can be "configuration" or "runtime", defaults to "configuration"
    :type distname_type: str
    :param connection: AdminConnection object or, if used, string name alias
    :type connection: AdminConnection or str
    :return configuration or runtime distname for particular cell
    :rtype: str
    :raises CellIdsNotFound: when cell wasn't matched with any of the cells on the BTS.
    """
    cells_parameters = _get_admin_cells_parameters(connection=connection)
    for cell in cells_parameters:
        if cell['RAT'] == cell_type and cell['CELLID'] == int(cell_id):
            return cell[f'{distname_type}DistName']
    raise CellIdsNotFound(f"Cell ID {cell_id} with {cell_type} type not found in current configuration.")


@log_input_and_output
def get_rmods_serial_numbers_and_runtime_dist_names(connection):
    """
    Returns serial numbers and runtime dist names of RMODs and ASIRMODs.
    :param connection: AdminConnection object or, if used, string name alias
    :type connection: AdminConnection or str
    :return: Dict containing serial numbers and runtime dist_names of RMODs and ASIRMODs, e.g: {"EA203150671":
    "MRBTS-10191/EQM_R-1/APEQM_R-1/RMOD_R-1", "EA203150671": "MRBTS-10191/EQM_R-1/APEQM_R-1/RMOD_R-2",
    "NH191503437": "MRBTS-10191/EQM_R-1/APEQM_R-1/ASIRMOD_R-1"}.
    :rtype: dict
    """
    unordered_output = {elem["serialNumber"]: elem["id"]["runtime"] for elem in _get_rmods_info(connection=connection)}
    priority_radios = get_radios_with_priority_in_chain(connection=connection)
    ordered_output = {sn: runtime_id for rmod in priority_radios for sn, runtime_id in unordered_output.items()
                      if rmod in runtime_id}
    ordered_output.update({sn: runtime_id for sn, runtime_id in unordered_output.items() if sn not in ordered_output})
    return ordered_output


