@log_input_and_output
def get_power_usage_for_rus(connection, runtime_ru_dist_names):
    """
    Gets real time power usage of given RMODs and ASIRMODs
    :param connection: AdminConnection object or if used, string name alias
    :type connection: AdminConnection or str
    :param runtime_ru_dist_names: runtime RMODs and ASIRMODs dist_names e.g.
                                  ["/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-1",
                                  "/MRBTS-1/RAT-1/RUNTIME_VIEW-4/MRBTS_R-4/EQM_R-4/APEQM_R-1/ASIRMOD_R-1"]
    :type runtime_ru_dist_names: list
    :return: dictionary with power usage for all given RMODs and ASIRMODs e.g. {"RMOD_R-1": 21.37, "ASIRMOD_R-2": 22.71}
    :rtype: dict
    """

    adm = admin()
    real_time_measurements = adm.get_measurements(connection=connection, measurement_type="realTime")
    power_usage = {}

    for device_measurement in real_time_measurements:
        for dist_name in runtime_ru_dist_names:
            ru_id = dist_name.split("/")[-1]
            device_key = "ENERGY_EFFICIENCY/RMOD/" + ru_id
            if device_key in device_measurement:
                power_usage[ru_id] = float(device_measurement[device_key]["power"])

    return power_usage


