@log_input_and_output
def check_if_given_parameters_have_expected_values(connection, dist_name, **parameters):
    """
    Checks if given parameters exist and have expected values
    :param connection: AdminConnection object or if used, string name alias
    :type connection: AdminConnection or str
    :param dist_name: dist_name path
    :type dist_name: str
    :param parameters: parameter names and its values to be validated. e.g. actMicroDtx=True,
                       allowTrafficConcentration=False
    :type parameters: dict
    :returns: information whether all parameters were found and have expected values
    :rtype: bool
    """
    parameters_to_verify = _get_parameters_for_given_dist_name(connection=connection, dist_name=dist_name)

    for param, value in parameters.items():
        try:
            if parameters_to_verify[param] != value:
                log_result("{}'s value for {} should be {}, is: {}".format(param, dist_name,
                                                                           value, parameters_to_verify[param]))
                return False
        except KeyError:
            log_result("{} parameter fo {} does not exist".format(param, dist_name))
            return False

    return True


@log_input_and_output
def get_rmod_index_from_dist_name(dist_name):
    """
    Returns index of RMOD/ASIRMOD from given dist_name
    :param dist_name: dist_name of RMOD/ASIRMOD
    :type dist_name: str
    :return: index extracted from dist_name
    """
    return int(dist_name.split('-')[-1])


@log_input_and_output
def get_rmod_details_with_rf_sw(connection):
    """
    Returns list of RMODs details including rf sw version.

    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :return: list of dicts with rmod details
    :rtype: list of dict
    """
    rmods_info = _get_parameters_for_all(connection=connection, hw_type="RMOD")

    try:
        return [
            {
                "serial_number": rmod_info["serialNumber"],
                "product_name": rmod_info["productName"],
                "sw_version": rmod_info["buildVersion"],
                "rmod_id": _get_id_from_dist_name(rmod_info["id"]),
            } for rmod_info in rmods_info
        ]

    except KeyError as e:
        raise ResponseFromApiChanged("Could not resolve API response due to: {}({})".format(e.__class__, e))


def get_rmod_sw_version(rmod_id, connection):
    """
    Returns sw version of RMOD/ASIRMOD with given id.

    :param rmod_id: Configuration RMOD/ASIRMOD id
    :type rmod_id: str or int
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :return: sw version of RMOD/ASIRMOD e.g. 'RF.FRU6.trunk.20250801.013'
    :rtype: str
    """
    rmods_info = get_rmod_details_with_rf_sw(connection)
    runtime_rmod_id = _get_rmod_ids_distnames(rmod_ids=rmod_id, connection=connection)[0]['runtime']['id']
    for rmod_info in rmods_info:
        if str(rmod_info["rmod_id"]) == str(runtime_rmod_id):
            return rmod_info["sw_version"]

    raise RmodSwVersionNotFound(f"Could not find sw version for RMOD with id: {rmod_id}")


