@log_input_and_output
def get_rmods_protocols(connection, dist_name_type="configuration"):
    """
    !!!THIS METHOD DOES NOT SUPPORT CONFIGURATIONS WITH BOTH RMODS AND ASIRMODS!!!
    Returns protocol types for all RMODs/ASIRMODs

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param dist_name_type: type of distname, can be 'configuration' (default) or 'internal' (RMODs/ASIRMODs are uncommissioned)
    :return: types of protocol for each RMOD/ASIRMOD (keys are configuration or internal ids depending on dist_name_type)
             e.g. {'1': 'CPRI', '2': 'eCPRI', '3': 'OBSAI', '4': 'ECPRI_NETCONF'}
    :rtype: dict
    :raises RmodProtocolNotFound: if RMOD protocol cannot be found in rmod parameters
    """
    rmods_parameters = get_rus_parameters(connection)
    rmod_internal_ids = get_rmod_indexes(connection=connection, dist_name_type="internal")
    if dist_name_type == "internal":
        rmod_config_ids = {config_id: config_id for config_id in rmod_internal_ids}
    else:
        rmod_config_ids = _translate_rmod_indexes_from_runtime(connection)
    rmods_protocols = {}

    for rmod_internal_id in rmod_internal_ids:
        for rmod_parameters in rmods_parameters:
            if int(rmod_parameters["id"].split("-")[-1]) == rmod_internal_id:
                if l3_protocol := rmod_parameters.get("l3Protocol"):
                    if re.findall(r"ECPRI_NETCONF", l3_protocol, re.IGNORECASE):
                        protocol = "ECPRI_NETCONF"
                    elif re.findall(r'ECPRI', l3_protocol, re.IGNORECASE):
                        protocol = "eCPRI"
                    elif re.findall(r"CPRI", l3_protocol, re.IGNORECASE):
                        protocol = "CPRI"
                    else:
                        protocol = "OBSAI"
                    rmods_protocols[str(rmod_config_ids[rmod_internal_id])] = protocol
                else:
                    raise RmodLinkProtocolNotFound(
                        f'RMOD parameter - `l3Protocol` cannot be found in rmod parameters, please check RMOD status '
                        f'in IMS log.\nRMOD available parameters: {rmod_parameters}.')
    return rmods_protocols


@log_input_and_output
def get_rmods_ran_protocols(connection, dist_name_type="configuration"):
    """
    Returns RAN protocols for all RMODs/ASIRMODs. If RMOD does not have protocol 'parameter' configured, the default
    value 'NOKIA' will be used.

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param dist_name_type: type of distname to be used to define dict keys, can be 'configuration' (default) or
                           'internal' (RMODs/ASIRMODs are uncommissioned)
    :type dist_name_type: str
    :return: types of RAN protocol for each RMOD/ASIRMOD (keys are configuration or internal ids depending on dist_name_type)
             e.g. {'1': 'O-RAN', '2': 'NOKIA'}
    :rtype: dict
    """
    adm = admin()
    rmods_distnames = get_rmods(connection=connection)
    rmods_config_indexes = [int(rmod.rsplit('-', 1)[-1]) for rmod in rmods_distnames]
    if dist_name_type == "internal":
        rmod_ids = _translate_rmod_indexes_to_runtime(connection)
    else:
        rmod_ids = {config_id: config_id for config_id in rmods_config_indexes}

    rmods_ran_protocols = {}
    rmods_with_missing_protocol = []
    for rmod_distname in rmods_distnames:
        ran_protocol = adm.get_parameter_by_distname(dist_name=rmod_distname, parameter_list=['protocol'],
                                                     connection=connection)
        rmod_distname_id = int(rmod_distname.rsplit('-', 1)[-1])
        try:
            rmods_ran_protocols[str(rmod_ids[rmod_distname_id])] = ran_protocol[0]['parameters']['protocol']
        except KeyError:
            rmods_ran_protocols[str(rmod_ids[rmod_distname_id])] = "NOKIA"
            rmods_with_missing_protocol.append(rmod_distname_id)

    log_env_state(
        f"For RMODs ID {rmods_with_missing_protocol} parameter - `protocol` cannot be found in parameters, "
        f"please check RMODs status in IMS log. Using default value 'NOKIA' for RAN protocol."
    )

    return rmods_ran_protocols


@log_input_and_output
def check_statuses_for_disabled_radio(connection):
    """
    Confirms that all RFM statuses are correct: Disabled/not initialized/Unlocked/NotInstalled.
    Exact status names are determined by StatusSelector based on current BTS SW version.
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :return: verification result
    :rtype bool
    """
    status_selector = StatusSelector()
    disabled = status_selector.select_operational_state(variant='disabled')
    not_installed = status_selector.select_availability_status(variant='not_installed')

    mrbts_list = get_ru_mrbts_by_operational_state(status=disabled, connection=connection)

    for mrbts in mrbts_list:
        adm_state = check_ru_parameter_status(dist_name=mrbts, parameter='administrativeState', connection=connection)
        av_state = check_ru_parameter_status(dist_name=mrbts, parameter='availabilityStatus', connection=connection)
        proc_state = check_ru_parameter_status(dist_name=mrbts, parameter='proceduralStatus', connection=connection)
        if adm_state != 'Unlocked' or av_state != not_installed or proc_state != 'not initialized':
            log_exception("Incorrect status for disabled radio")
            log_exception(mrbts)
            return False
    return True


@log_input_and_output
@raise_when_output_is_empty
def get_ru_mrbts_by_operational_state(status, connection):
    """
    Returns MRBTS for RMODs and ASIRMODs by selected operational status
    :param status: ex. Enabled, Disabled
    :type status: str
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :return: list of MRBTS
    :rtype list of str
    """
    return [rmod['id']['internal'] for rmod in _get_rmods_info(connection=connection)
            if str(status) == rmod['status']['operationalState']]


