@log_input_and_output
def match_cell_dist_names_with_config_id(connection, cell_type, cell_config_id):
    """
    Matches both runtime and config dist_names with given cell config id.
    :param connection: AdminConnection object or if used, string name alias
    :type connection: AdminConnection or str
    :param cell_type: cell type of given RAT: "lte", "wcdma", "gsm", "nr"
    :type cell_type: str
    :param cell_config_id: id of the cell that we want to match
    :type cell_config_id: str or int
    :return: dict with matched runtime and config cell dist_names
             e.g. [{"run_time": "/MRBTS-1/RUN/TIME/CELL_R-1", "configuration": "/MRBTS-1/CFG/CELL-1"}]
    :rtype: dict
    :raises ObjectNotFound: when cell's id wasn't match with any cell
    """
    cells = _get_cells_dist_names(connection=connection, cell_type=cell_type)
    for cell in cells:
        if cell["configuration"].split("-")[-1] == str(cell_config_id):
            return cell

    raise ObjectNotFound("Cell with config id: {}, couldn't be matched to runtime object".format(cell_config_id))


@log_input_and_output
def get_physical_cell_id(connection, cell_dist_name):
    """
    Gets physical cell id
    :param connection: AdminConnection object or if used, string name alias
    :type connection: AdminConnection or str
    :param cell_dist_name: cell config dist_name
    :type cell_dist_name: str
    :return: physcial cell id
    :rtype: int
    """
    adm = admin()
    cells_info = adm.get_cell_list(connection=connection)["cells"]
    for rat in cells_info.values():
        for cell in rat:
            if cell["id"]["configuration"] == cell_dist_name:
                return cell["physicalCellId"]

    raise ObjectNotFound("Couldn't find physical cell id of {}".format(cell_dist_name))


@log_input_and_output
def _get_cells_dist_names(connection, cell_type):
    adm = admin()
    cells_info = adm.get_cell_list(connection=connection)["cells"][cell_type]

    return [
        {"run_time": cell["id"]["internal"], "configuration": cell["id"]["configuration"]} for cell in cells_info]


