def get_cells_config_ids_for_rmod_per_rat(rmod_internal_distname, connection):
    """
    Returns dict with list of cells config ids that are connected to provided RMOD/ASIRMOD.
    :param rmod_internal_distname: RMOD/ASIRMOD internal dist name
    :type rmod_internal_distname: str
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :return: dict with list of cells config ids per rat, e.g. {'lte': ['1', '2'], 'nr': ['3', '4']}
    :rtype: dict(str, list[str])
    """
    cell_ids_per_rat = defaultdict(list)

    for cell in _get_cell_mapping_for_rmod(rmod_internal_distname=rmod_internal_distname, connection=connection):
        cell_ids_per_rat[cell['RAT']].append(cell['configurationDistName'].split('-')[-1])

    return dict(cell_ids_per_rat)


def get_runtime_id_for_rmod(connection, rmod_id):
    """
    !!!THIS METHOD DOES NOT SUPPORT CONFIGURATIONS WITH BOTH RMODS AND ASIRMODS!!!
    Gets runtime RMOD/ASIRMOD ID based on provided RMOD/ASIRMOD configuration ID
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param rmod_id: RMOD/ASIRMOD configuration ID
    :type rmod_id: str
    :return: runtime id of RMOD/ASIRMOD
    :rtype: str
    :raises ParameterDoesNotExist when runtime id of RU with provided id could not be found.
    """
    for elem in _get_rmods_info(connection=connection):
        if elem['id']['configuration'].split('-')[-1] == str(rmod_id):
            return elem['id']['runtime'].split('-')[-1]

    raise ParameterDoesNotExist("Runtime ID of RMOD with ID: {0} could not be found".format(rmod_id))


def get_serial_number_for_rmod(connection, rmod_id):
    """
    !!!THIS METHOD DOES NOT SUPPORT CONFIGURATIONS WITH BOTH RMODS AND ASIRMODS!!!
    Gets RMOD/ASIRMOD serial number
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param rmod_id: RMOD/ASIRMOD configuration ID
    :type rmod_id: str
    :return: serial number of RMOD/ASIRMOD
    :rtype: str
    :raises ParameterDoesNotExist when serial number of RMOD/ASIRMOD with provided id could not be found.
    """
    for elem in _get_rmods_info(connection=connection):
        if elem['id']['configuration'].split('-')[-1] == str(rmod_id):
            return elem['serialNumber']

    raise ParameterDoesNotExist("Serial number of RMOD with ID: {0} could not be found".format(rmod_id))


def get_local_id_for_rmod_by_serial_number(connection, rmod_serial_number):
    """
    !!!THIS METHOD DOES NOT SUPPORT CONFIGURATIONS WITH ASIRMODS!!!
    Gets local RMOD ID based on provided RMOD's serial number
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param rmod_serial_number: RMOD's serial number
    :type rmod_serial_number: str
    :return: local id of RMOD
    :rtype: str
    :raises ParameterDoesNotExist when local id of RU with provided serial number could not be found.
    """
    rmod_l_objects = _get_managed_objects_for_class(connection, "RMOD_L")

    for l_object in rmod_l_objects:
        if l_object['parameters']['serialNumber'] == rmod_serial_number:
            return l_object['distName'].split("RMOD_L-")[-1]

    raise ParameterDoesNotExist("Local ID of RMOD with serial number: {0} could not be found".
                                format(rmod_serial_number))


