@log_input_and_output
def configure_l1_iq_data_collection(sw_stream, connection, dist_name=None, dl_nr_subcell_list=None,
                                    ul_nr_subcell_list=None, dl_lte_subcell_list=None, ul_lte_subcell_list=None,
                                    capture_on_event=False, capture_on_event_bb_ru=False, profile=None,
                                    buffer_cycle=None, capture_frame_offset=None, capture_ru_list=None, timeout=120):
    """
    Configures UPlaneL1IQData log collection (Diagnostic ->  Debug tracing -> UPlane Component -> L1-IQ capture).
    For NR cells list should for be constructed as follows:
        [
            {"nrcellDN": "MRBTS-2137/NRBTS-2137/NRCELL-1", "subcellId": 0},
            {"nrcellDN": "MRBTS-2137/NRBTS-2137/NRCELL-2", "subcellId": 1},
        ]
    For LTE cells list should for be constructed as follows:
        [
            {"lnCelId":1,"subId":0},
            {"lnCelId":2,"subId":1}
        ]
    :param sw_stream: SW stream on BTS, e.g. 'SBTS25R2'
    :type sw_stream: str
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param dist_name: BBMOD configuration distname
    :type dist_name: str
    :param dl_nr_subcell_list: list of nr cells that will be captured in L1-IQ logs for DL
    :type dl_nr_subcell_list: list[dict] or None
    :param ul_nr_subcell_list: list of nr cells that will be captured in L1-IQ logs for UL
    :type ul_nr_subcell_list: list[dict] or None
    :param dl_lte_subcell_list: list of lte cells that will be captured in L1-IQ logs for DL
                                Not applicable when 'capture_on_event_bb_ru' is True.
    :type dl_lte_subcell_list: list[dict] or None
    :param ul_lte_subcell_list: list of lte cells that will be captured in L1-IQ logs for UL.
                                Not applicable when 'capture_on_event_bb_ru' is True.
    :type ul_lte_subcell_list: list[dict] or None
    :param capture_on_event: if True, the capture on event option will be enabled. Defaults to False.
    :type capture_on_event: bool
    :param capture_on_event_bb_ru: if True, the capture on event from BBU and RU option will be enabled.
                                   Defaults to False.
    :type capture_on_event_bb_ru: bool
    :param profile: profile which represents different capture mode, default None (means no profile is set).
                    Should be used only when "capture_on_event_bb_ru" = True and sw_stream >= 'SBTS25R3'.
                    Allowed values are:
                    'UL_PROFILE_1', 'UL_PROFILE_2', 'UL_PROFILE_3', 'DL_PROFILE_1', 'UL_DL_PROFILE_1'.
                    When “capture_on_event_bb_ru” = True and “capture_on_event” = True, Event type profiles are allowed.
                    When “capture_on_event_bb_ru” = True and “capture_on_event” = False, Blind type profiles are allowed.
    :type profile: str or None
    :param buffer_cycle: buffer cycle, one of following: "2frames"/"4frames"/"8frames"/"16frames"/"32frames"/
                         "64frames"/"128frames"/"256frames"/"512frames"/"1024frames"/None, only applicable when
                         'capture_on_event_bb_ru' is True, default None.
    :type buffer_cycle: str or None
    :param capture_frame_offset: capture frame offset from range [0...1023], defaults None means capture frame offset
                                 is not set.
    :type capture_frame_offset: int or str or None
    :param capture_ru_list: list of RMODs to be configured with detailed parameters, each ru element should be defined
                            as dictionary and should contain following parameters: targetRMOD (str type: RMOD
                            configuration DN), antennaList (list type: dict as element with following
                            keys: "polarization" (str type: "MINUS_45"/"PLUS_45"/"PLUS_90"/"ZERO")
                            and "antenna" (list type: integer array or string array) captureActivityTimer
                            (int type: range 1 to 12), e.g.:
                            [{ "targetRMOD": "/RMOD_R-1",
                               "antennaList": [{"polarization": "PLUS_45",
                                                "antenna": ["ANT1"]},
                                               {"polarization": "MINUS_45",
                                                "antenna": [1,2,3]}],
                               "captureActivityTimer": 2}];
                            defaults to None.
    :type capture_ru_list: list[dict] or None
    :param timeout: timeout (in seconds) for admin operation, default set 120
    :type timeout: int
    :return: returns "Succeeded" in case of configure_uplane_l1_iq_data operation success, None otherwise.
    :rtype: str or None
    """
    validated_capture_frame_offset = None if capture_frame_offset is None else int(capture_frame_offset)

    if not dist_name and sw_stream < 'SBTS25R3':
        raise MissingArgument("To configure IQ data collection dist_name must be provided for SW streams below "
                              "SBTS25R3")
    elif sw_stream > 'SBTS25R2' and dist_name:
        dist_name = None
        log_warning('BBMOD configuration distname ("dist_name") is not supported for SW streams SBTS25R3 and above, '
                    'it will be ignored.')

    if capture_on_event_bb_ru and sw_stream > 'SBTS25R2':
        if not profile:
            raise MissingArgument("To configure capture on event from BBU and RU, profile must be provided for SW "
                                  "streams SBTS25R3 and above")
    elif profile and sw_stream < 'SBTS25R3':
        log_warning('Profile ("profile") is not supported for SW streams below SBTS25R3, it will be ignored.')
        profile = None

    if capture_on_event_bb_ru and not capture_ru_list:
        raise MissingArgument("To configure capture on event from BBU and RU, capture ru list must be provided")

    adm = admin()
    return adm.configure_uplane_l1_iq_data(connection=connection,
                                           module_dn=dist_name,
                                           capture_on_event=capture_on_event,
                                           dl_nr_subcell_list=dl_nr_subcell_list,
                                           ul_nr_subcell_list=ul_nr_subcell_list,
                                           dl_lte_subcell_list=dl_lte_subcell_list,
                                           ul_lte_subcell_list=ul_lte_subcell_list,
                                           capture_on_event_bb_ru=capture_on_event_bb_ru,
                                           profile=profile,
                                           capture_ru_list=capture_ru_list,
                                           buffer_cycle=buffer_cycle,
                                           capture_frame_offset=validated_capture_frame_offset,
                                           timeout=timeout)


