def get_serial_numbers_of_all_smods(connection):
    """
    Returns SMODs serial numbers.
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str.
    :return: serial number of all SMODs.
    :rtype: [str]
    """
    adm = admin()
    smods_info = adm.get_parameters_for_all(class_name='SMOD', connection=connection)
