def get_serial_number_for_smod(connection, smod_id, smod_id_type='runtime'):
    """
    Returns SMOD serial number for provided SMOD id.
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param smod_id: SMOD id
    :type smod_id: int, str
    :param smod_id_type: SMOD id type, one of 'runtime' or 'configuration', default 'runtime'
    """
    smods_info = _get_bts_info(connection)['systemModules']

    for smod_info in smods_info:
        if str(smod_id) == smod_info['id'][smod_id_type].split('-')[-1]:
            return smod_info['serialNumber']

    raise ObjectNotFound(f"SMOD with {smod_id_type} id: {smod_id} not found")


@log_input_and_output
def get_runtime_antennas_for_cell(cell_dist_name, connection):
    """
    Gets runtime dist names of antenna objects for cell.
    :param cell_dist_name: configuration or run-time dist name for cell
           (e.g. 'MRBTS-40615/NRBTS-40615/NRCELL-0' or
                 '/MRBTS-1/RAT-1/RUNTIME_VIEW-4/MRBTS_R-4/NRBTS_R-40615/NRCELL_R-0')
    :type cell_dist_name: str
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :return: list of runtime antennas' dist names for cell
    """
    adm = admin()
    info = adm.get_cell_specific_info(cell_id=cell_dist_name, connection=connection)
    runtime_antennas = []
    for ant_info in info['carrierList']:
        runtime_antennas.append(ant_info['antennaLineId']['internal'])

    return list(set(runtime_antennas))


