@log_input_and_output
def verify_x2_link_status(connection, bts_setup, expected_state='available'):
    """
    Verifies X2 link status.
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param expected_state: expected state of X2 link, default 'available'
    :type expected_state: str
    :param bts_setup: BTS setup type, one of 'SA' or 'NSA'.
    :type bts_setup: str
    :raises ObjectNotFound: If LTE eNB X2 Link object does not exist in NSA setup.
    :raises IncorrectX2LinkStateDetected: If detected X2 Link status is not as expected.
    """
    if lte_enb_node_object := get_managed_objects_for_class(object_class_name='LTEENB_R', connection=connection):
        x2link_status = lte_enb_node_object[0]['parameters']['x2LinkStatus']
    elif lnadjgnb_object := get_managed_objects_for_class(object_class_name='LNADJGNB_A', connection=connection):
        x2link_status = lnadjgnb_object[0]['parameters']['x2ToGnbLinkStatus']
    elif bts_setup == "NSA":
        raise ObjectNotFound("LTE eNB X2 Link Object Does Not Exist in NSA setup")
    else:
        log_result("LTE eNB X2 Link Does Not Exist")
        return

    if x2link_status != expected_state:
        raise IncorrectX2LinkStateDetected(f"Detected incorrect X2 Link status: detected '{x2link_status}', "
                                           f"should be: '{expected_state}'")

    log_result(f"X2 Link in correct state: '{expected_state}'")


