def get_rmods_sync_status(connection, rmod_ids, id_type="configuration"):
    """
    Gets 'syncStatus' from RMODs.
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param rmod_ids: List of RMOD ids for which sync status should be checked e.g. [1, 2].
    :type rmod_ids: int, str, list[int | str]
    :param id_type: Type of RMOD id, one of 'internal', 'configuration' or 'runtime', default 'configuration'.
    :type id_type: str
    :return: rmod ids with syncStatus e.g. {'1': 'Locked', '2': 'Locked'}
    :rtype: dict
    :raises ObjectNotFound: If RMOD ID from the provided argument `rmod_ids` cannot be found in the list from AdminApi containing all RMODs on BTS.
    """
    all_rmod_r = _get_managed_objects_for_class(connection, "RMOD_R")
    all_clock_r = _get_managed_objects_for_class(connection, "CLOCK_R")
    rmods = _get_rmod_ids_distnames(rmod_ids=rmod_ids, connection=connection, id_type=id_type)

    rmod_r_lookup = {r['distName'].split('/')[-1]: r for r in all_rmod_r}
    clock_r_lookup = {clock_r['parameters']['targetDN']: clock_r['parameters'].get('syncStatus') for clock_r in all_clock_r}

    rmods_with_sync_status = {}
    for rmod in rmods:
        rmod_runtime_distn = rmod['runtime']['distname']
        rmod_r_configdn = rmod_r_lookup[rmod_runtime_distn.split('/')[-1]]['parameters'].get('configDN')
        rmod_sync_status = clock_r_lookup[rmod_r_configdn]
        rmods_with_sync_status[rmod[id_type]['id']] = rmod_sync_status

    return rmods_with_sync_status


def get_rmods_dl_ul_min_delay(rmod_ids, connection, id_type='configuration'):
    """
    Gets parameters 'dlMinDelay' and 'ulMinDelay' cablink/loglink values for provided RMOD(s).
    :param rmod_ids: List of RMOD ids for which 'dlMinDelay' and 'ulMinDelay' values should be taken.
    :type rmod_ids: list[int | str]
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param id_type: Type of RMOD id, one of 'internal', 'configuration' or 'runtime', default 'configuration'.
    :type id_type: str
    :return: rmod ids with 'dlMinDelay' and 'ulMinDelay' values e.g.
             {'1': {'CABLINK_R-1001': {'dlMinDelay': [800, 817], 'ulMinDelay': [500, 496]}}}
    :rtype: dict
    :raises ObjectNotFound: If RMOD ID from the provided argument `rmod_ids` cannot be found in the list from AdminApi containing all RMODs on BTS.
    :raises ParameterDoesNotExist: If 'dlMinDelay' and 'ulMinDelay' values could not be found for all RMOD ids.
    """
    rmods = _get_rmod_ids_distnames(rmod_ids=rmod_ids, connection=connection, id_type=id_type)
    all_rmods_links = _get_cablinks_distnames_for_all_rmods(connection=connection, rmod_id_type=id_type)

    if not all_rmods_links:
        all_rmods_links = _get_loglinks_distnames_for_all_rmods(connection=connection, rmod_id_type=id_type)

    all_fhlkdly_r = _get_managed_objects_for_class(connection, "FHLKDLY_R")
    fhlkdly_r_lookup = [f['distName'].split('/')[-2] for f in all_fhlkdly_r]

    rmods_dl_ul_delays = {}
    for rmod in rmods:
        rmod_id = rmod[id_type]['id']
        rmod_link_runtime_ids = [c['runtime'].split('/')[-1] for c in all_rmods_links[int(rmod_id)]]
        rmods_dl_ul_delays[rmod_id] = {
            link_runtime_id: {
                'dlMinDelay': [f['parameters']['dlMinDelay'] for f in all_fhlkdly_r if f['distName'].split('/')[-2] == link_runtime_id],
                'ulMinDelay': [f['parameters']['ulMinDelay'] for f in all_fhlkdly_r if f['distName'].split('/')[-2] == link_runtime_id]
            }
            for link_runtime_id in rmod_link_runtime_ids if link_runtime_id in fhlkdly_r_lookup
        }

    if not all(value for value in rmods_dl_ul_delays.values()):
        raise ParameterDoesNotExist(f"Parameters dlMinDelay and 'ulMinDelay' could not be found for all {id_type} RMOD ids {rmod_ids}\n"
                                    f"Result: {rmods_dl_ul_delays}")

    return rmods_dl_ul_delays


