@log_input_and_output
def get_bts_alarm_history(connection, severity=None, load_history=True, from_time=None, timeout=60):
    """
    Gets BTS alarms history.

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param severity: Alarm severity, one of  "critical", "major", "minor", "warning"
    :type severity: str
    :param load_history: If True, loads full alarm history, default True
    :type load_history: bool
    :param from_time: Get alarms from specific time, default None means all alarms e.g
    :type from_time: utc datetime
    :param timeout: Timeout (in seconds) for admin operation, default set 60
    :type timeout: int
    """
    adm = admin()
    alarms = adm.get_historic_alarms(timeout=timeout, connection=connection, severity=severity, load_history=load_history)
    if from_time:
        alarms = [alarm for alarm in alarms if alarm['eventTime'] >= int(from_time.timestamp()) * 1000]

    return alarms


