@log_input_and_output
def get_cell_statuses(connection, cells_distnames=None):
    """
    Gets statuses from all cells on BTS if arg 'cells_distnames' not provided otherwise for provided cell dist name(s).
    Cell statuses include:
     for NR: 'administrativeState', 'operationalState', 'usageState', 'blockingState', 'proceduralStatus', 'barringStatus', 'energySavingState'
     for LTE: 'administrativeState', 'operationalState', 'usageState', 'blockingState', 'energySavingState'

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param cells_distnames: Cell configuration dist name(s). Default None means all configured cells.
                            (e.g. 'MRBTS-40615/NRBTS-40615/NRCELL-0' or ['MRBTS-40615/NRBTS-40615/NRCELL-0', 'MRBTS-40615/LNBTS-40615/LNCEL-0'])
    :type cells_distnames: None | str | list[str]
    :return: dict with cell configuration dist names as keys and their statuses as values
             e.g. {'MRBTS-40615/NRBTS-40615/NRCELL-0': {'operationalState': 'disabled', ...},
                   'MRBTS-40615/LNBTS-40615/LNCEL-0': {'operationalState': 'enabled', ...}}
    :rtype: dict[str, dict[str, any]]
    :raises CellInfoNotFound: If any of the provided cells could not be found or no statuses could be fetched for them.
    """
    cell_distns = convert_to_list(cells_distnames) if cells_distnames else []
    cells_statuses = _get_cell_statuses(connection)

    if cell_distns:
        cells_statuses = {cell: cells_statuses[cell] for cell in cell_distns if cells_statuses.get(cell)}

    if missing_cells := [cell for cell in cell_distns if cell not in cells_statuses]:
        raise CellInfoNotFound(f"Cells: {missing_cells} not found on BTS.")

    if cells_without_statuses := [cell for cell in cells_statuses if not cells_statuses[cell]]:
        raise CellInfoNotFound(f"Could not fetch any statuses for cells: {cells_without_statuses}.")

    return cells_statuses


@log_input_and_output
def is_rmod_massive_mimo(connection, rmod_distn):
    """
    Checks whether the RMOD with given configuration dist name is massive mimo.

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param rmod_distn: RMOD configuration dist name, e.g. 'MRBTS-50104/EQM-1/APEQM-1/RMOD-1'
    :type rmod_distn: str
    :return: True if RMOD is mMIMO, else False
    :rtype: bool
    :raises ParameterDoesNotExist: if RMOD serial number could not be found for given RMOD dist name,
                                   & if RMOD_L dist name could not be found for given RMOD serial number
    :raises ValueError: if 'isMassiveMimo' parameter is not found for RMOD_L object
    """
    rmod_l_dist_name = _get_rmod_l_obj_dist_name(connection=connection, rmod_dist_name=rmod_distn)
    searched_rmod_obj = f'{rmod_l_dist_name}/RMOD_BP_L-1'
    log_result(f"RMOD configuration dist name: {rmod_distn}, RMOD_L dist name: {rmod_l_dist_name}")

    return get_parameter_value_from_object(dist_name=searched_rmod_obj, parameter_name="isMassiveMimo", connection=connection)


