def get_rmods_from_power_saving_groups(connection, power_saving_groups):
    """
    Gets RMOD configuration dist names from provided Power Saving Groups.

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param power_saving_groups: Power Saving Group or list of Power Saving Groups configuration dist names,
                                e.g. 'MRBTS-50589/NRBTS-50589/NRPGRP-1' or ['MRBTS-50589/NRBTS-50589/NRPGRP-1', 'MRBTS-50589/LNBTS-50589/PSGRP-1']
    :type power_saving_groups: str | list[str]
    :return: list of RMODs configuration dist names, e.g. ['MRBTS-40612/EQM-1/APEQM-1/RMOD-1', 'MRBTS-40612/EQM-1/APEQM-1/RMOD-2']
    :rtype: list[str]
    """
    power_saving_groups = convert_to_list(power_saving_groups)
    rmod_distns = set()
    for psg in power_saving_groups:
        cell_distnames = disable_logging(get_cell_distnames_from_power_saving_groups, connection=connection, power_group_distnames=psg)
        for cell in cell_distnames:
            rmod_distnames = _get_rmod_by_cell_distn(connection=connection, cell_distn=cell)
            rmod_distns.update(rmod_distnames)

    return list(rmod_distns)


def get_rmod_sync_clock_dist_name(connection, rmod_dist_names):
    """
    Gets the configuration synchronization clock dist name for given RMOD.

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param rmod_dist_names: str or list of RMOD configuration dist names,
           e.g. 'MRBTS-40612/EQM-1/APEQM-1/RMOD-1' or ['MRBTS-40612/EQM-1/APEQM-1/RMOD-1', 'MRBTS-40612/EQM-1/APEQM-1/RMOD-2']
    :type rmod_dist_names: str or list[str]
    :return: dict with RMOD configuration dist names as keys and their synchronization clock dist name as value, e.g.
             {'MRBTS-40612/EQM-1/APEQM-1/RMOD-1': 'MRBTS-1174/MNL-1/MNLENT-1/SYNC-1'}
    :rtype: dict[str, str]
    :raises ObjectNotFound: If synchronization clock dist name could not be found for any of the provided RMOD configuration dist names.
    """
    rmod_dist_names = [rmod_dist_names] if isinstance(rmod_dist_names, str) else rmod_dist_names

    sync_dist_names = _get_parameters_by_class(connection=connection, class_name='SYNC', parameters=['targetDNList'])
    sync_with_rmods = {
        sync_distn: data['targetDNList']
        for sync_distn, data in sync_dist_names.items()
        if data.get('targetDNList')
    }

    rmods_with_sync = {
        rmod: sync
        for rmod in rmod_dist_names
        for sync, rmods in sync_with_rmods.items()
        if rmod in rmods
    }

    if missing := [rmod for rmod in rmod_dist_names if rmod not in rmods_with_sync]:
        raise ObjectNotFound(f"No synchronization clock dist name found for RMOD(s) with dist name(s): {missing}")

    return rmods_with_sync


