@log_input_and_output
def get_serial_numbers_and_product_codes_of_all_modules(connection):
    """
    Gets serial numbers and product codes of all modules (CABINET, SMOD, BBMOD, RMOD, ASIRMOD) from admin.
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :return: dictionary with modules' product codes and serial numbers, e.g. :
             {'CABINETs': [{'product_code': '473098A'},
                           {'product_code': '473098B'}],
              'SMODs': [{'serial_number': 'L1232304192', 'product_code': '474767A.103'},
                        {'serial_number': 'L1232304183', 'product_code': '474767X.101'}],
              'BBMODs': [{'serial_number': 'L1232004108', 'product_code': '475792A.101'},
                         {'serial_number': 'L1232004111', 'product_code': '475792A.103'}],
              'RMODs': [{'serial_number': 'AH221500786', 'product_code': '475432A.101'},
                        {'serial_number': 'AH221500678', 'product_code': '475432A.103'}]}
    :rtype: dict[str, list[dict[str, str]]]
    """
    bts_info = _get_bts_info(connection)

    cabinets = [{'product_code': cabinet['productCode']} for cabinet in bts_info['cabinets']]
    smods = [{'serial_number': smod['serialNumber'], 'product_code': smod['productCode']} for smod in bts_info['systemModules']]
    bbmods = [{'serial_number': bbmod['serialNumber'], 'product_code': bbmod['productCode']} for bbmod in bts_info['basebandModules']]
    rmods = [{'serial_number': rmod['serialNumber'], 'product_code': rmod['productCode']} for rmod in bts_info['radioModules']['rmod']]
    asirmods = [{'serial_number': asirmod['serialNumber'], 'product_code': asirmod['productCode']} for asirmod in bts_info['radioModules']['asirmod']]

    return {'CABINETs': cabinets, 'SMODs': smods, 'BBMODs': bbmods, 'RMODs': rmods + asirmods}


@log_input_and_output
def _get_runtime_bbmod_object_name_for_connected_rmod(rmod_id, link_mode, connection):
    """
    !!!THIS METHOD DOES NOT SUPPORT CONFIGURATIONS WITH ASIRMODS!!!
    Gets list of runtime BBMOD object names for given RMOD id with particular link mode connection.
    :param rmod_id: configuration RMOD id connected to BBMOD by synchronization/data/configuration link, e.g.: '1'.
    :type rmod_id: int or str
    :param link_mode: link mode of connection between BBMODs and given RMOD
    :type link_mode: str
    :param connection: AdminConnection object or, if used, string name alias
    :type connection: AdminConnection or str
    :return: list of runtime object name of BBMOD with connection to given RMOD's synchronization/data/configuration
             link: e.g: ['BBMOD_R-1', 'BBMOD_R-2']
    :rtype: list
    """
    adm = admin()
    cablinks_info = adm.get_bts_info(connection=connection)['cables']

    bbmod_runtime_objects = []
    for cablink in cablinks_info:
        if f"RMOD-{rmod_id}/" in cablink['secondEndPointId']['configuration']:
            if cablink['linkMode'][link_mode]:
                runtime_bbmod = re.search(r'BBMOD_R-(\d+)', cablink['firstEndPointId']['runtime'])
                if runtime_bbmod:
                    bbmod_runtime_objects.append(runtime_bbmod.group())

    return bbmod_runtime_objects


@log_input_and_output
def _get_cell_mapping_for_rmod(rmod_internal_distname, connection, sort_cells_by_chbw=False, reverse_order=False):
    adm = admin()
    cell_mapping = adm.get_cell_mapping_by_module_id(module_id=rmod_internal_distname, connection=connection)
    cells_parameters = _get_admin_cells_parameters(connection=connection, sort_cells_by_chbw=sort_cells_by_chbw,
                                                   reverse_order=reverse_order)

    return [cell_info for cell_info in cells_parameters if cell_info['runtimeDistName'] in cell_mapping]


@log_input_and_output
def _get_admin_cells_parameters(connection, sort_cells_by_chbw=False, reverse_order=False):
    adm = admin()
    cell_info_output = {'nr': adm.get_cells_info(connection=connection, cell_type="nr"),
                        'lte': adm.get_cells_info(connection=connection, cell_type="lte"),
                        'wcdma': adm.get_cells_info(connection=connection, cell_type="wcdma"),
                        'gsm': adm.get_cells_info(connection=connection, cell_type="gsm")
                        }
    cell_info_output = {rat: cell_info for rat, cell_info in cell_info_output.items() if cell_info != []}
    cells_parameters = []

    for rat in cell_info_output:
        cell_id_name = _get_name_of_id_param_depending_on_cell_type(rat)
        for cell in cell_info_output[rat]:
            cell_params = cell
            cell_params["runtimeDistName"] = cell["id"]["internal"]
            cell_params["configurationDistName"] = cell["id"]["configuration"]
            cell_params['RAT'] = rat
            cell_params['CELLID'] = cell[cell_id_name] if cell_id_name is not None else \
                int(cell['id']['configuration'].split('-')[-1])
            if rat.upper() == "GSM":
                cell_params['channelBandwidth'] = "0.2 MHz"

            cells_parameters.append(cell_params)

    if sort_cells_by_chbw:
        cells_parameters = _sort_list_of_cells_by_chbw(list_of_cells_parameters=cells_parameters, reverse=reverse_order)

    return cells_parameters


