@log_input_and_output
def _get_cells_for_all_rmods(connection):
    """
    Gets all RMODs with their cells.

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :return: dictionary with configuration RMOD id as key and list of cells' names
             e.g {'1': ['NRCELL-23', 'NRCELL-22'], '14': ['LNCEL-62', 'LNCEL-63']}
    :rtype: dict
    """
    cell_ids_for_all_rmods = {}
    for frm in _get_rmods_info(connection=connection):
        try:
            rmod_id = frm['ports'][0]['id']['configuration'].split("/")[-2].split("-")[-1]
        except KeyError:
            rmod_id = frm["id"]["configuration"].split("/")[-1].split("-")[-1]

        carrier_list = _get_cells_for_rmod(frm=frm)
        cell_ids_for_all_rmods[rmod_id] = carrier_list

    return cell_ids_for_all_rmods


@log_input_and_output
def _get_cells_for_rmod(frm):
    cells = []
    for index, carrier in enumerate(frm['carrierList']):
        cell_id = frm['carrierList'][index]['id']['configuration'].split("/")[-2]
        if cell_id not in cells:
            cells.append(cell_id)

    return cells


