@log_input_and_output
def _get_dependent_rmods(connection, runtime_rmod_id):
    cablink_connections = {rmod: connections for rmod, connections in _get_cablink_connections(connection).items()
                           if "RMOD" in rmod}
    chains = _get_chains_for_all_rmods(cablink_connections)
    dependent = []
    for rmod, chain in chains.items():
        if f'RMOD_R-{runtime_rmod_id}' in chain or f'ASIRMOD_R-{runtime_rmod_id}' in chain:
            dependent.append(rmod)
    return dependent


@log_input_and_output
def _get_chains_for_all_rmods(cablink_connections):
    return {runtime_rmod: _get_chain_for_rmod(cablink_connections, runtime_rmod)
            if _is_rmod_chained(cablink_connections, runtime_rmod) else
            [runtime_rmod] for runtime_rmod in cablink_connections}


@log_input_and_output
def _get_chain_for_rmod(cablink_connections, runtime_rmod):
    explored, queue = [], [[runtime_rmod]]
    while queue:
        queue, explored, optimal_path = _explore_rmod_connections(queue, explored, cablink_connections)
        if optimal_path:
            return optimal_path


@log_input_and_output
def _explore_rmod_connections(queue, explored, cablink_connections):
    path_to_bbmod = queue.pop(0)
    node = path_to_bbmod[-1]
    if node not in explored:
        for neighbour in cablink_connections[node]:
            new_path = list(path_to_bbmod)
            new_path.append(neighbour)
            queue.append(new_path)
            if not _is_rmod_chained(cablink_connections, neighbour):
                return queue, explored, new_path
        explored.append(node)
    return queue, explored, None


@log_input_and_output
def _is_rmod_chained(cablink_connections, runtime_rmod):
    for device in cablink_connections[str(runtime_rmod)]:
        if "BBMOD" in device or "FHS" in device or "SMOD" in device:
            return False
    return True


@log_input_and_output
def _get_cablink_connections(connection):
    cablinks = _get_parameters_for_all(connection=connection, hw_type="CABLINK")
    connections = {}
    for cablink in cablinks:
        first_endpoint, second_endpoint = \
            cablink['firstEndpointDN'].split("/")[-1], cablink['secondEndpointDN'].split("/")[-1]
        connections = _add_to_dict_both_ways(first_endpoint, second_endpoint, connections)

    return connections


def _add_to_dict_both_ways(first_value, second_value, dictionary):
    dictionary = _add_to_dict(first_value, second_value, dictionary)
    return _add_to_dict(second_value, first_value, dictionary)


def _add_to_dict(key, value, dictionary):
    if key in dictionary:
        if value not in dictionary[key]:
            dictionary[key].append(value)
    else:
        dictionary[key] = [value]

    return dictionary


