@log_input_and_output
def _get_cell_technology(connection, cell_type, cell_id):
    if cell_type == "wcdma" or cell_type == "gsm":
        log_env_state("Cell technology is available only for NR and LTE cells")
        return None
    class_name = _get_class_name_depending_on_rat(cell_type=cell_type)
    cells_runtime_distnames = _get_cell_distnames(
        connection=connection, cell_type=cell_type
    )

    cells_technology = _get_cells_technology_dict(
        class_name=class_name,
        cells_runtime_distnames=cells_runtime_distnames,
        connection=connection,
    )

    return cells_technology[str(cell_id)]


@log_input_and_output
def _get_cells_technology_dict(class_name, cells_runtime_distnames, connection):
    adm = admin()
    cells_technology = {}

    for cell in cells_runtime_distnames:
        parameters = adm.get_parameters_for(
            class_name=class_name, id_num=cell, connection=connection
        )
        if cell in cells_technology:
            cells_technology[cell.split("-")[-1]].append(parameters["technology"])
        else:
            cells_technology[cell.split("-")[-1]] = parameters["technology"]
    return cells_technology


