@log_input_and_output
def _get_rats(connection):
    rats = []
    for rat in ["lte", "wcdma", "gsm", "nr"]:
        cells = _get_all_cells_without_guardband_and_inband_iot_cells(connection=connection, rat=rat)
        if cells:
            rats.append(rat)
    if rats:
        return rats
    raise CellInfoNotFound("Admin method output for cell info was empty!")


@log_input_and_output
def _get_all_cells_without_guardband_and_inband_iot_cells(connection, rat):
    adm = admin()
    filtered_cells = []
    for cell in (adm.get_cells_info(cell_type=rat, connection=connection) or []):
        technology = cell.get("technology", '')
        narrowband_mode = cell.get("narrowbandIotMode", '')
        if not ('IoT' in technology and ('guardband' in narrowband_mode or 'inband' in narrowband_mode)):
            filtered_cells.append(cell)
    return filtered_cells


