@log_input_and_output
def _is_cell_shared(connection, cell_id, cell_type):
    """
    !!!THIS METHOD DOES NOT SUPPORT CONFIGURATIONS WITH BOTH RMODS AND ASIRMODS!!!
    Determines whether cell of given cell_type and cell_id is shared between more than one RMOD/ASIRMOD.
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param cell_type: Cell type of given RAT: "lte", "wcdma", "gsm", "nr"
    :type cell_type: str
    :param cell_id: ID of cell
    :param cell_id: int or str
    :return: info whether given cell is shared between more than one RMOD/ASIRMOD
    :rtype: bool
    """
    return isinstance(_get_rmod_ids_for_cell_id(connection, cell_id, cell_type), list)


def _sort_list_of_cells_by_chbw(list_of_cells_parameters, reverse=False):
    return sorted(list_of_cells_parameters, key=_get_chbw_as_float_from_cell_parameters, reverse=reverse)


def _get_chbw_as_float_from_cell_parameters(cell_parameters):
    channel_bandwidth_possible_param_names = ["chBw", "chBwDl", "channelBandwidth", "downlinkChannelBandwidth"]

    for key in channel_bandwidth_possible_param_names:
        if cell_parameters.get(key):
            return float(re.search(r"\d+(\.\d+)?", cell_parameters[key]).group())

    raise ParameterDoesNotExist(f"Neither of the parameters related to channel bandwidth "
                                f"({channel_bandwidth_possible_param_names}) was found in cell parameters: "
                                f"{cell_parameters}")


@log_input_and_output
def _get_statuses_of_all_cells(cells_type, connection):
    """
    Gets statuses of all cells with given type
    :param cells_type: type of cells, can be "nr", "lte", "wcdma" or "gsm"
    :type cells_type: str
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :return: statuses for cells with configuration cell id as key (str) and cell statuses as value (dict), e.g.:
              {"1": {"operationalState": 'enabled', "administrativeState": "unlocked",
                     "usageState": "Idle", "blockingState": "Unblocked"},
               "2": {"operationalState": 'enabled', "administrativeState": "unlocked",
                     "usageState": "Idle", "blockingState": "Blocked"}}
    :rtype: dict
    """
    adm = admin()
    id_param_name = _get_name_of_id_param_depending_on_cell_type(cells_type)
    bts_cells_info = adm.get_bts_info(connection=connection)["cells"][cells_type]
    cells_statuses = {}
    for cell_info in bts_cells_info:
        cell_id = cell_info[id_param_name] if id_param_name is not None else \
            cell_info['id']['configuration'].split('-')[-1]
        cells_statuses[str(cell_id)] = cell_info['status']

    return cells_statuses


def _get_all_rmods_ids_distnames(connection):
    """
    Gets all RMODs ids and distnames.
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :return: list of RMODs with 'internal', 'configuration' and 'runtime' ids and distnames e.g
        [{'internal': {'id': '1', 'distname': '/MRBTS-1/RAT-1/RUNTIME_VIEW-4/MRBTS_R-4/EQM_R-4/APEQM_R-1/RMOD_R-1'},
          'configuration': {'id': '1', 'distname': 'MRBTS-40612/EQM-1/APEQM-1/RMOD-1'},
          'runtime': {'id': '1', 'distname': 'MRBTS-40612/EQM_R-4/APEQM_R-1/RMOD_R-1'}}]
    :rtype: list[dict]
    """
    all_rmods = []
    bts_rmods_info = _get_bts_info(connection=connection)["radioModules"]

    for rmod_type, rmods in bts_rmods_info.items():
        for rmod in rmods:
            rmod_dict = {
                key: {
                    "id": (rmod['id'].get(key).split('-')[-1] if rmod['id'].get(key) else None),
                    "distname": rmod['id'].get(key)
                }
                for key in ['internal', 'configuration', 'runtime']
            }
            all_rmods.append(rmod_dict)

    return all_rmods


def _get_rmod_ids_distnames(rmod_ids, connection, id_type="configuration"):
    """
    Gets 'internal', 'configuration', 'runtime' ids and distnames for given RMOD ids.

    :param rmod_ids: List of RMOD ids for which 'internal', 'configuration' and 'runtime' values should be taken.
    :type rmod_ids: int | str | list[int | str]
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param id_type: Type of RMOD id(s) provided in arg: `rmod_ids`, one of 'internal', 'configuration' or 'runtime', default 'configuration'.
    :type id_type: str
    :return: list of RMODs with 'internal', 'configuration' and 'runtime' ids and distnames e.g
        [{'internal': {'id': '1', 'distname': '/MRBTS-1/RAT-1/RUNTIME_VIEW-4/MRBTS_R-4/EQM_R-4/APEQM_R-1/RMOD_R-1'},
          'configuration': {'id': '1', 'distname': 'MRBTS-40612/EQM-1/APEQM-1/RMOD-1'},
          'runtime': {'id': '1', 'distname': 'MRBTS-40612/EQM_R-4/APEQM_R-1/RMOD_R-1'}}]
    :rtype: list[dict]
    :raises ObjectNotFound: if RMOD with provided id not found in all rmods from admin info model.
    """
    all_rmods = _get_all_rmods_ids_distnames(connection=connection)

    if not isinstance(rmod_ids, list):
        rmod_ids = [rmod_ids]

    rmods = [next((r for r in all_rmods if str(rmod_id) == r[id_type]['id']), None) for rmod_id in rmod_ids]
    if None in rmods:
        missing_ids = [rmod_ids[i] for i, r in enumerate(rmods) if r is None]
        raise ObjectNotFound(f"RMOD(s) with id(s): {missing_ids} not found in list with all rmods from BTS:\n"
                             f"All {id_type} rmod ids from BTS: {[rmod[id_type]['id'] for rmod in all_rmods]}")
    return rmods


