def _get_power_saving_groups(connection, rats=None):
    """
    Gets power saving groups details.
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param rats: list of RATs for which power saving groups should be fetched, e.g. ['nr', 'lte'].
                 If None, all available RATs on BTS will be used. Default None.
    :type rats: list[str] | str | None
    :return: dict with RATs as keys and list of dicts with power saving groups parameter values, e.g.:
            {'nr': [{'distName': 'MRBTS-50589/NRBTS-50589/NRPGRP-1', 'parameters': ...},
                    {'distName': 'MRBTS-50589/NRBTS-50589/NRPGRP-2', 'parameters': ...}],
             'lte': [{'distName': 'MRBTS-50589/LNBTS-50589/PSGRP-0', 'parameters': ...}]}
    :rtype: dict
    """
    adm = admin()

    if not rats:
        rats = _get_rats(connection=connection)
    rats = [rats] if isinstance(rats, str) else rats
    power_group_by_rat = {'nr': 'NRPGRP', 'lte': 'PSGRP'}

    return {rat: adm.get_parameter_by_class(class_name=power_group_by_rat[rat], connection=connection) for rat in rats}


def _get_parameters_by_distname(connection, dist_name, parameters=None):
    """
    [admin api only]
    Gets parameters for given distname.

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param dist_name: Distname of the object from which the parameter should be checked,
                      e.g. 'MRBTS-40615/LNBTS-40615/LNCEL-0'
    :type dist_name: str
    :param parameters: Parameter name or list of parameter names to be fetched. Default None means fetches all parameters,
                       e.g. 'searched_parameter' or ['searched_parameter1', 'searched_parameter2']
    :type parameters: str or list[str] or None
    :return: dict with parameter names as keys and their value, e.g.:
             {'searched_parameter1': 'value1', 'searched_parameter2': 'value2'}
    :rtype: dict[str, str]
    :raises MissingParametersError: if any parameters could not be retrieved for the specified distname,
                                    or if any required parameters are missing from the response
    """
    if isinstance(parameters, str):
        parameters = [parameters]

    results = admin().get_parameter_by_distname(dist_name=dist_name, parameter_list=parameters, connection=connection)
    matched_obj_parameters = next((r['parameters'] for r in results if r['distName'] == dist_name), None)

    if matched_obj_parameters is None:
        raise MissingParametersError(f"Could not find distname: {dist_name} on the BTS")

    if not parameters:
        return matched_obj_parameters

    fetched_parameters = {p: matched_obj_parameters.get(p) for p in parameters}
    if missing_params := [param for param in parameters if fetched_parameters[param] is None]:
        raise MissingParametersError(f"Could not fetch parameters: {missing_params} for distname: {dist_name}")

    return fetched_parameters


def _get_cell_statuses(connection):
    """
    Gets statuses of all cells on the BTS.
    Included statuses:
      for NR: 'administrativeState', 'operationalState', 'usageState', 'blockingState', 'proceduralStatus', 'barringStatus', 'energySavingState'
      for LTE: 'administrativeState', 'operationalState', 'usageState', 'blockingState', 'energySavingState'

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :return: dict with cell configuration dist name as keys and dict with all mandatory statuses as values,
             e.g. {'MRBTS-40615/NRBTS-40615/NRCELL-0': {'operationalState': 'disabled', ...},
                   'MRBTS-40615/LNBTS-40615/LNCEL-0': {'operationalState': 'enabled', ...}}
    :rtype: dict
    """
    all_cells_info = disable_logging(admin().get_bts_info, connection=connection)["cells"]

    cells_statuses = {}
    for cell_type, cells in all_cells_info.items():
        for cell in cells:
            cell_config_distn = cell['id']['configuration']
            statuses = cell['status']
            statuses |= {'energySavingState': cell['energySavingState']} if cell.get('energySavingState') else {}
            cells_statuses[cell_config_distn] = statuses

    return cells_statuses


def _get_cell_id_type_from_distname(configuration_distn):
    """
    Extract cell ID and type from configuration dist name.

    :param configuration_distn: configuration dist name of cell, e.g. 'MRBTS-40612/NRBTS-50612/NRCELL-3'
    :type configuration_distn: str
    :return: tuple of cell ID and cell type, e.g. ('3', 'nr')
    :rtype: tuple(str, str)
    """
    cell_class, cell_id = configuration_distn.split("/")[-1].split('-')
    cell_type = _get_rat_depending_on_class_name(cell_class)
    return cell_id, cell_type


@log_input_and_output
def _get_rmod_l_obj_dist_name(connection, rmod_dist_name):
    """
    Gets the RMOD_L Info model Viewer obj dist name.

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param rmod_dist_name: configuration dist name, e.g. 'MRBTS-50104/EQM-1/APEQM-1/RMOD-1'
    :type rmod_dist_name: str
    :return: RMOD_L managed object dist name, e.g. '/MRBTS-1/RAT-1/BTS_L-4/EQM_L-1/RMOD_L-1'
    :rtype: str
    :raises ParameterDoesNotExist: if RMOD_L dist name could not be found for given RMOD configuration dist name.
    """
    rmod_l_objects = disable_logging(_get_managed_objects_for_class, connection, "RMOD_L")
    rmod_sn = disable_logging(get_serial_number_for_rmod, connection=connection, rmod_id=rmod_dist_name.split('-')[-1])

    for l_object in rmod_l_objects:
        if l_object['parameters']['serialNumber'] == rmod_sn:
            return l_object['distName']

    raise DistnameForRmodNotFound(f"RMOD_L dist name could not be found for RMOD: {rmod_dist_name}")


def _get_rmod_by_cell_distn(connection, cell_distn):
    """
    Gets RMOD(s) associated with given cell.

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param cell_distn: cell configuration dist name, e.g. 'MRBTS-40612/NRCELL-1'
    :type cell_distn: str
    :return: list of RMOD(s) configuration dist names associated with given cell, e.g.
             ['MRBTS-40612/EQM-1/APEQM-1/RMOD-1'] or ['MRBTS-40612/EQM-1/APEQM-1/RMOD-1', 'MRBTS-40612/EQM-1/APEQM-1/RMOD-2']
    :rtype: list[str]
    :raises DistnameForRmodNotFound: if no RMOD(s) found for given cell dist name.
    """
    all_rmods_with_cells = _get_cells_for_all_rmods(connection)

    rmods = set()
    cell_name = cell_distn.split('/')[-1]
    for rmod, cells in all_rmods_with_cells.items():
        if cell_name in cells:
            rmod_distn = disable_logging(_get_config_distname_for_rmod, connection=connection, config_rmod_id=rmod)
            rmods.add(rmod_distn)
            log_result(f'Found RMOD configuration dist name: {rmod_distn} for cell: {cell_distn}')

    if not rmods:
        raise DistnameForRmodNotFound(f"Could not found RMOD(s) for cell with dist name: {cell_distn}")

    return list(rmods)


def _get_cell_a_obj_type(cell_type):
    """
    Gets the CELL_A Info model Viewer object type based on cell type.

    :param cell_type: cell type of given RAT: "lte", "wcdma", "gsm", "nr"
    :type cell_type: str
    :return: CELL_A managed object type, e.g. 'NRCELL_A', 'LNCEL_A'
    :rtype: str
    :raises InvalidRATtype: if provided cell type is invalid.
    """
    cell_a_obj_mapping = {'lte': 'LNCEL_A', 'nr': 'NRCELL_A', 'wcdma': 'WNCEL_A', 'gsm': 'GNCEL_A'}
    try:
        return cell_a_obj_mapping[cell_type]
    except KeyError:
        raise InvalidRATtype(f"Provided RAT type does not exist: {cell_type}")


def _get_bts_sync_input_types(connection):
    """
    Gets BTS synchronization input type(s).

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :return: BTS synchronization input type, e.g.
             {'1pps/ToD from external GNSS receiver': {'sync_prio': 1, 'is_active': True}}
    :rtype: dict
    """
    sync_source_info = admin().get_bts_sync_source_status(connection=connection).get('syncSourceInfo')
    if not sync_source_info:
        raise ParameterDoesNotExist("No sync source info found on BTS!")

    sync_inputs = {
        src.get('syncInputType'): {'sync_prio': src.get('syncInputPrio'), 'is_active': src.get('isActive')}
        for src in sync_source_info
    }

    return sync_inputs


def _get_parameters_by_class(connection, class_name, parameters=None, include_children=False):
    """
    Gets parameters for given class name.

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param class_name: Name of the class from which the parameter should be checked, e.g. 'NRCELL_R'
    :type class_name: str
    :param parameters: Parameter name or list of parameter names to be fetched. Default None means fetches all parameters,
                       e.g. 'searched_parameter' or ['searched_parameter1', 'searched_parameter2']
    :param include_children: whether to include parameters of child objects of given class in result, default False
    :type include_children: bool
    :return: dict with dist names as keys and dict with parameters as values, e.g.
             {'MRBTS-40615/NRBTS-40615/NRCELL-0': {'operationalState': 'disabled', ...},
              'MRBTS-40615/NRBTS-40615/NRCELL-1': {'operationalState': 'enabled', ...}}
    :rtype: dict
    :raises MissingParametersError: if any parameters could not be retrieved for the specified class name
    """
    parameters = parameters if parameters is None or isinstance(parameters, list) else [parameters]
    response = admin().get_parameter_by_class(class_name=class_name, connection=connection, parameter_list=parameters,
                                              include_children=include_children)
    result = {}
    for item in response:
        raw_params = item.get('parameters', {})
        filtered = {p: raw_params[p] for p in parameters if p in raw_params} if parameters else raw_params
        if filtered:
            result[item['distName']] = filtered

    if parameters and not result:
        raise MissingParametersError(f"Could not find any parameters for class: {class_name}")

    return result


def _get_parameters_with_childrens_by_dist_name(connection, dist_name, parameters=None):
    """
    Gets parameters for given dist name including its children objects.

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param dist_name: configuration dist name, e.g. 'MRBTS-50570/MNL-1/MNLENT-1/SYNC-1'
    :type dist_name: str
    :param parameters: Parameter or list of parameters which can be found in admin info for specific object dist name and its children objects.
                       Default None means fetch all parameters, e.g. 'shutdownWindow', ['lcrId', 'p_max'].
    :type parameters: str | list[str]
    :return: dict with dist name as key and dict of parameter names as keys and their values as value, e.g.:
             {'MRBTS-50570/MNL-1/MNLENT-1/SYNC-1/CLOCK-1/CLOCK_R-1': {'searched_parameter2': 'value2'}
              'MRBTS-50570/MNL-1/MNLENT-1/SYNC-1/CLOCK-1/CLOCK_R-2': {'searched_parameter1': 'value1'}}
    :rtype: dict[dict[str, str]]
    :raises MissingParametersError: if any parameters could not be retrieved for the specified dist name,
    """
    if isinstance(parameters, str):
        parameters = [parameters]

    results = admin().get_parameter_by_distname(dist_name=dist_name, parameter_list=parameters, connection=connection, include_children=True)

    distns_with_params = {}
    for item in results:
        d_name = item.get('distName', '')
        raw_params = item.get('parameters', {})

        if dist_name in d_name and raw_params:
            filtered = {k: v for k, v in raw_params.items() if k in parameters} if parameters else raw_params

            if filtered:
                distns_with_params[d_name] = filtered

    if not parameters:
        return distns_with_params

    found_params = {p for p_list in distns_with_params.values() for p in p_list}
    if missing := [p for p in parameters if p not in found_params]:
        raise MissingParametersError(f"Could not find parameters: {missing}")

    return distns_with_params
